window.ScripturaLexicons.BDAG_PART_0104 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirgasamen-eigas-mai-bdag\" data-source=\"BDAG\" data-search=\"εἰργασάμην, εἴγασμαι eirgásamēn, eígasmai formas verbais; remissão ver ἐργάζομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰργασάμην, εἴγασμαι</td><td>formas verbais; remissão</td><td>ver ἐργάζομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eireka-eirekei-eiremai-bdag\" data-source=\"BDAG\" data-search=\"εἴρηκα, εἰρήκει, εἴρημαι eírēka, eirḗkei, eírēmai formas verbais; remissão ver εἶπον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἴρηκα, εἰρήκει, εἴρημαι</td><td>formas verbais; remissão</td><td>ver εἶπον</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirenaios-bdag\" data-source=\"BDAG\" data-search=\"Εἰρηναῖος, ου, ὁ Eirēnaîos nome próprio masculino Ireneu, bispo de Lião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Εἰρηναῖος, ου, ὁ</td><td>nome próprio masculino</td><td>Ireneu, bispo de Lião</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirenarchos-bdag\" data-source=\"BDAG\" data-search=\"εἰρήναρχος, ου, ὁ eirḗnarchos substantivo masculino chefe de polícia; magistrado policial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰρήναρχος, ου, ὁ</td><td>substantivo masculino</td><td>chefe de polícia; magistrado policial</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eireneuo-bdag\" data-source=\"BDAG\" data-search=\"εἰρηνεύω eirēneúō verbo reconciliar; estar em paz; conservar a paz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰρηνεύω</td><td>verbo</td><td>reconciliar; estar em paz; conservar a paz</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirene-bdag\" data-source=\"BDAG\" data-search=\"εἰρήνη, ης, ἡ eirḗnē substantivo feminino paz; harmonia; bem-estar; salvação messiânica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰρήνη, ης, ἡ</td><td>substantivo feminino</td><td>paz; harmonia; bem-estar; salvação messiânica</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirenikos-bdag\" data-source=\"BDAG\" data-search=\"εἰρηνικός, ή, όν eirēnikós adjetivo pacífico; promotor da paz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰρηνικός, ή, όν</td><td>adjetivo</td><td>pacífico; promotor da paz</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirenopoieo-bdag\" data-source=\"BDAG\" data-search=\"εἰρηνοποιέω eirēnopoiéō verbo fazer a paz; reconciliar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰρηνοποιέω</td><td>verbo</td><td>fazer a paz; reconciliar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirenopoios-bdag\" data-source=\"BDAG\" data-search=\"εἰρηνοποιός, όν eirēnopoiós adjetivo; substantivo pacificador; aquele que promove a paz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰρηνοποιός, όν</td><td>adjetivo; substantivo</td><td>pacificador; aquele que promove a paz</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eirusmai-bdag\" data-source=\"BDAG\" data-search=\"εἴρυσμαι eírysmai forma verbal; remissão ver ῥύομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἴρυσμαι</td><td>forma verbal; remissão</td><td>ver ῥύομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eironeia-bdag\" data-source=\"BDAG\" data-search=\"εἰρωνεία, ας, ἡ eirōneía substantivo feminino dissimulação; fingimento; afetação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰρωνεία, ας, ἡ</td><td>substantivo feminino</td><td>dissimulação; fingimento; afetação</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eis-preposition-bdag\" data-source=\"BDAG\" data-search=\"εἰς eis preposição com acusativo em; para; para dentro de; até; com referência a; a fim de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰς</td><td>preposição com acusativo</td><td>em; para; para dentro de; até; com referência a; a fim de</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heis-numeral-bdag\" data-source=\"BDAG\" data-search=\"εἷς, μία, ἕν heîs, mía, hén numeral cardinal e adjetivo pronominal um; uma; um só; o primeiro; alguém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἷς, μία, ἕν</td><td>numeral cardinal e adjetivo pronominal</td><td>um; uma; um só; o primeiro; alguém</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eisago-bdag\" data-source=\"BDAG\" data-search=\"εἰσάγω eiságō verbo introduzir; conduzir para dentro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰσάγω</td><td>verbo</td><td>introduzir; conduzir para dentro</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eisakouo-bdag\" data-source=\"BDAG\" data-search=\"εἰσακούω eisakoúō verbo obedecer; ouvir e atender; escutar preces BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰσακούω</td><td>verbo</td><td>obedecer; ouvir e atender; escutar preces</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eisdechomai-bdag\" data-source=\"BDAG\" data-search=\"εἰσδέχομαι eisdéchomai verbo receber graciosamente; acolher; admitir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰσδέχομαι</td><td>verbo</td><td>receber graciosamente; acolher; admitir</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eiseimi-go-bdag\" data-source=\"BDAG\" data-search=\"εἴσειμι eíseimi verbo entrar; ir para dentro; dirigir-se a alguém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἴσειμι</td><td>verbo</td><td>entrar; ir para dentro; dirigir-se a alguém</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eiserchomai-bdag\" data-source=\"BDAG\" data-search=\"εἰσέρχομαι eisérchomai verbo entrar; ingressar; participar; acontecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰσέρχομαι</td><td>verbo</td><td>entrar; ingressar; participar; acontecer</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eisegagon-bdag\" data-source=\"BDAG\" data-search=\"εἰσηγαγον eisḗgagon forma verbal; remissão ver εἰσάγω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰσηγαγον</td><td>forma verbal; remissão</td><td>ver εἰσάγω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eisegeomai-bdag\" data-source=\"BDAG\" data-search=\"εἰσηγέομαι eisēgéomai verbo aplicar; mobilizar; empenhar; introduzir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰσηγέομαι</td><td>verbo</td><td>aplicar; mobilizar; empenhar; introduzir</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-eirgasamen-eigas-mai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰργασάμην, εἴγασμαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirgásamēn, eígasmai⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>E outras formas: veja <span class=\"greek\">ἐργάζομαι</span>.</p></div></section></article> <article id=\"entry-eireka-eirekei-eiremai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴρηκα, εἰρήκει, εἴρημαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eírēka, eirḗkei, eírēmai⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">εἶπον</span>.</p></div></section></article> <article id=\"entry-eirenaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εἰρηναῖος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Eirēnaîos⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Inscrições, papiros; Josefo, Bell. 2, 21.) <strong>Ireneu, bispo de Lião</strong>, MPol 22:2; Epílogo de Moscou 1s., 4s.</p></div></section></article> <article id=\"entry-eirenarchos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰρήναρχος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirḗnarchos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(De <span class=\"greek\">εἰρήνη</span> e <span class=\"greek\">ἄρχομαι</span>; IMilet I/7, 263, 7; IGR IV, 1543; SEG XLI, 1044, 5; POxy 1507, 1; 1662, 19; PAm 139, 3s. e 11 [350 d.C.]; 146, 2 [século V d.C.].) <strong>Magistrado do período imperial; chefe de polícia, comandante policial</strong>, MPol 6:2; 8:2. — Lightfoot, ad loc.; W. Liebenam, Städteverwaltung im römischen Kaiserreich, 1900, 358. — Veja DELG, s.v. <span class=\"greek\">ἄρχω</span> C, p. 120.</p></div></section></article> <article id=\"entry-eireneuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰρηνεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirēneúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Veja <span class=\"greek\">εἰρήνη</span>.) Futuro <span class=\"greek\">εἰρηνεύσω</span>, 1Cl 56:12s.; primeiro aoristo <span class=\"greek\">εἰρήνευσα</span>, LXX; infinitivo <span class=\"greek\">εἰρηνεῦσαι</span>, 1Cl 63:4.</p>\n<p><strong>① Fazer outros viverem em paz; reconciliar</strong>, transitivo (Cássio Díon 77, 12; 1Mac 6:60), com acusativo <span class=\"greek\">τινά</span>, «alguém» (cf. Políbio 5, 8, 7; Cat. Cod. Astr. IX/2, p. 145, 16): os que estão em desavença, B 19:12; D 4:3.</p>\n<p><strong>② Estar em paz</strong>, intransitivo (em geral, referente ao fim de um estado de inimizade ou hostilidade; Platão, Theaet. 180b; Cássio Díon 42, 15; IBM 894, 8s.: <span class=\"greek\">εἰρηνεύουσι γῆ καὶ θάλαττα</span>, «a terra e o mar estão em paz»; LXX; TestSol; TestJob 36:4; Test12Patr).</p>\n<p><strong>ⓐ Viver em paz, estar em paz</strong> (IBM 894; 2Cr 14:5; Jó 3:26; 2Mac 12:4), com dativo <span class=\"greek\">τινί</span>, «com alguém» (Jó 5:23; Sir 6:6), 1Cl 56:12. Da assembleia de Deus, isto é, a Igreja, que desfruta de paz, IPhld 10:1; cf. ISm 11:2; IPol 7:1. <span class=\"greek\">ἐν σαρκὶ καὶ πνεύματι</span>, «em paz exterior e interiormente», ITr, inscrição; <span class=\"greek\">εἰρηνεῦσαι</span>, «alcançar a paz», 1Cl 63:4.</p>\n<p><strong>ⓑ Manter a paz</strong>, de modo absoluto (Apiano, Liby. 67 §303; Syr. 4 §15; Bell. Civ. 5, 22 §88; TestGad 6:6), 2Co 13:11. <span class=\"greek\">δαιμόνιον μηδέποτε εἰρηνεῦον</span>, «um espírito [inquieto] que nunca mantém a paz», Hm 2:3. <span class=\"greek\">εἰρηνεύετε ἐν ἀλλήλοις</span>, «mantende a paz uns com os outros» (Vi. Aesopi W 102 P.: <span class=\"greek\">εἰρ</span>. <span class=\"greek\">πρὸς ἀλλήλους</span>, variante <span class=\"greek\">εἰς ἀλλ</span>.), Mc 9:50 (A. van Veldhuizen, Zout en Vrede, NThSt 15, 1932, 252–259). Para isso também <span class=\"greek\">ἐν ἑαυτοῖς</span>, 1Ts 5:13; Hv 3, 6, 3; 3, 9, 2 e 10; 3, 12, 3; Hs 8, 7, 2. <span class=\"greek\">μετά τινος</span>, «com alguém» (3Rs 22:45; TestBenj 5:1), Rm 12:18; 1Cl 54:2. <span class=\"greek\">οἱ εἰρηνεύοντες</span>, «os pacíficos, aqueles que vivem em paz» (Sir 28:9, 13), 1Cl 15:1. — DELG, s.v. <span class=\"greek\">εἰρήνη</span>. M-M. TW. Spicq.</p></div></section></article> <article id=\"entry-eirene-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰρήνη, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirḗnē⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Veja <span class=\"greek\">εἰρηνεύω</span>; Homero e seguintes. <span class=\"greek\">εἰρήνη</span> e termos correlatos são frequentes em textos astrológicos, por exemplo Cat. Cod. Astr. IX/2, p. 173, 21; 175, 10.)</p>\n<p><strong>① Estado de concórdia; paz, harmonia.</strong></p>\n<p><strong>ⓐ Entre governos</strong>, em oposição a <span class=\"greek\">πόλεμος</span>, «guerra», IEph 13:2. <span class=\"greek\">ἐρωτᾷ τὰ πρὸς εἰρήνην</span>, «pede condições de paz», Lc 14:32 (cf. TestJud 9:7: <span class=\"greek\">αἰτοῦσιν ἡμᾶς τὰ πρὸς εἰρήνην</span>, «pedem-nos condições de paz»; Ana Comnena, Alex. 8, 5, ed. R. II, p. 12, 17: <span class=\"greek\">τὰ περὶ εἰρήνης ἐρωτῶντες</span>, «indagando sobre a paz». Também é possível traduzir por «pergunta por sua saúde», como <span class=\"greek\">ἐρωτᾷ</span> [<span class=\"greek\">τὰ</span>] <span class=\"greek\">εἰς εἰρήνην</span>, correspondente ao hebraico <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">שָׁאַל</bdi> <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">לְשָׁלוֹם</bdi>, 2Rs 8:10; 11:7; veja H. Thackeray, JTS 14, 1913, 389–399; Helbing, Kasussyntax 40). <span class=\"greek\">ἐν εἰ</span>. <span class=\"greek\">εἶναι</span>, «estar em paz, fora de perigo» (Aristóteles, Mirabilia 119, 842a 2), Lc 11:21; <span class=\"greek\">λαμβάνειν τὴν εἰ</span>. <span class=\"greek\">ἔκ τινος</span>, «tirar a paz de algum lugar», isto é, lançá-lo em estado de guerra, Ap 6:4; At 24:2. Dos combatentes: <span class=\"greek\">αἰτεῖσθαι εἰ</span>., «pedir paz» (Anônimo, História de Alexandre [século II a.C.], 151 Fgm. 1, 5 Jac.), At 12:20.</p>\n<p><strong>ⓑ Harmonia nas relações pessoais; paz, concórdia.</strong> Juntamente com <span class=\"greek\">ὁμόνοια</span>, «concordância de ânimo» (Crisipo, Stoic. II 1076; Diodoro Sículo 16, 60, 3; Díon Crisóstomo 21 [38], 14; 22 [39], 2; SIG 685, 13 [139 a.C.]; Josefo, Ant. 4, 50), 1Cl 60:4; 61:1; 63:2; com <span class=\"greek\">πραΰτης</span>, «mansidão», 61:2; em oposição a <span class=\"greek\">ὀργή</span>, «ira», D 15:3; e a <span class=\"greek\">μάχαιρα</span>, «espada», Mt 10:34; cf. Lc 12:51. <span class=\"greek\">συναλλάσσειν εἰς εἰ</span>., «pacificar», At 7:26; <span class=\"greek\">σύνδεσμος τῆς εἰ</span>., «vínculo da paz», Ef 4:3; <span class=\"greek\">βασιλεὺς εἰρήνης</span>, «rei da paz» (como tradução de Salém; cf. Fílon, Leg. All. 3, 79), Hb 7:2.</p>\n<p>Da comunidade cristã: <span class=\"greek\">εἰ</span>. <span class=\"greek\">ἔχειν</span>, «ter paz, repouso» [da perseguição, como em At 14:2, variante; sobre a expressão, Diodoro Sículo 11, 72, 1; cf. Josefo, Bell. 2, 401], At 9:31; <span class=\"greek\">εἰ</span>. <span class=\"greek\">βαθεῖα</span>, «paz profunda» (Ath. 1, 3 [em oposição a <span class=\"greek\">διώκεσθαι</span>, «ser perseguido»]; veja <span class=\"greek\">βαθύς</span> ③ⓐ), 1Cl 2:2. <span class=\"greek\">ὁδὸς εἰρήνης</span>, «caminho da paz, que leva à paz», Rm 3:17 (Sl 13:3; Is 59:8); Lc 1:79; <span class=\"greek\">μετ</span>’ <span class=\"greek\">εἰρήνης</span>, «pacificamente» (Diodoro Sículo 3, 18, 7; Vi. Aesopi W 97 P.: <span class=\"greek\">μετ</span>’ <span class=\"greek\">εἰρήνης ζῆν</span>, «viver em paz»; EpJer 2; 1Esdr 5:2; 1Mac 12:4, 52 e outros; Josefo, Ant. 1, 179; 8, 405), Hb 11:31.</p>\n<p><span class=\"greek\">ποιεῖν εἰ</span>., «fazer a paz» (Hermocles [séculos IV/III a.C.], Anth. Lyr. II, p. 250, 21 [p. 174, 21 Coll. Alex. = Ateneu 6, 253e]: <span class=\"greek\">πρῶτον μὲν εἰρήνην ποίησον</span>, <span class=\"greek\">φίλτατε</span>, «primeiramente, faz a paz, meu caro»; com <span class=\"greek\">ἐπί τινα</span>, Ireneu 4, 40, 1 [Harv. II 301, 9]), At 14:2, variante; Ef 2:15; <span class=\"greek\">οἱ ποιοῦντες εἰ</span>., «os que fazem a paz», Tg 3:18. <span class=\"greek\">βούλεσθαι εἰ</span>., «desejar a paz» (Pv 12:20), 1Cl 15:1; <span class=\"greek\">διώκειν</span>, «buscar a paz» (juntamente com <span class=\"greek\">δικαιοσύνη</span>, «justiça», <span class=\"greek\">πίστις</span>, «fé», e <span class=\"greek\">ἀγάπη</span>, «amor»), 2Tm 2:22; Gl 5:22; 1Cl 22:5 (Sl 33:15); <span class=\"greek\">εἰ</span>. <span class=\"greek\">διώκειν μετὰ πάντων</span>, «esforçar-se para viver em paz com todos», Hb 12:14 (cf. Epicteto 4, 5, 24: <span class=\"greek\">εἰ</span>. <span class=\"greek\">ἄγεις πρὸς πάντας</span>, «manténs paz com todos»). <span class=\"greek\">τὰ τῆς εἰ</span>. <span class=\"greek\">διώκειν</span>, «buscar aquilo que promove a paz», Rm 14:19; <span class=\"greek\">ζητεῖν εἰ</span>., «procurar a paz», 1Pe 3:11 (Sl 33:15); cf. 2Cl 10:2; <span class=\"greek\">τὰ πρὸς εἰ</span>., «as coisas que contribuem para a paz», Lc 19:42.</p>\n<p>Com <span class=\"greek\">ἀσφάλεια</span>, «segurança», 1Ts 5:3; com <span class=\"greek\">ἀγάπη</span>, «amor», B 21:9; 1Cl 62:2. <span class=\"greek\">ἀπέστη ἡ εἰ</span>., «a paz desapareceu», 1Cl 3:4 (cf. <span class=\"greek\">δαίμονας</span> … <span class=\"greek\">τὴν εἰ</span>. <span class=\"greek\">ταράσσοντας</span>, «demônios perturbadores da paz», Orígenes, C. Cels. 8, 73, 29). <span class=\"greek\">πρόσωπον εἰρήνης ἔχειν</span>, «manter uma fachada de paz», Hv 3, 6, 3; <span class=\"greek\">εἰ</span>. <span class=\"greek\">ἔχειν ἐν ἑαυτοῖς</span>, «manter paz dentro de seu próprio grupo», 3, 5, 1.</p>\n<p><strong>ⓒ Boa ordem</strong>, em oposição a <span class=\"greek\">ἀκαταστασία</span>, «desordem», 1Co 14:33; cf. 7:15 e 1Cl 20:1, 9ss.</p>\n<p><strong>② Estado de bem-estar; paz.</strong></p>\n<p><strong>ⓐ Correspondente ao hebraico <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">שָׁלוֹם</bdi>; bem-estar, saúde.</strong> (W. Caspari, Vorstellung und Wort ‘Friede’ im AT, 1910, especialmente p. 128ss.) Em saudação de despedida: <span class=\"greek\">ὑπάγειν ἐν εἰ</span>., «ir em paz», aproximadamente equivalente a «passar bem», Tg 2:16; também <span class=\"greek\">πορεύεσθαι ἐν εἰ</span>. (Jz 18:6 B; 2Rs 3:21), At 16:36; <span class=\"greek\">ὑπάγειν εἰς εἰρήνην</span>, Mc 5:34; <span class=\"greek\">πορεύεσθαι εἰς εἰ</span>. (1Rs 1:17; 20:42; 29:7; Jd 8:35), Lc 7:50; 8:48. <span class=\"greek\">προπέμπειν τινὰ ἐν εἰ</span>., «encaminhar alguém em paz», 1Co 16:11 (cf. Vi. Aesopi I, 32, p. 297, 1 Eberhard: <span class=\"greek\">ἐν εἰρήνῃ ἀπέστειλεν</span> [<span class=\"greek\">αὐτόν</span>], «despediu-o em paz»); <span class=\"greek\">ἐν εἰ</span>. <span class=\"greek\">μετὰ χαρᾶς ἀναπέμψατε</span>, «enviai de volta em paz e com alegria», 1Cl 65:1; <span class=\"greek\">ἀπολύειν τινὰ μετὰ εἰρήνης</span>, «despedir alguém com uma saudação de paz», At 15:33 (cf. Gn 26:29; Josefo, Ant. 1, 179).</p>\n<p>Na fórmula de saudação <span class=\"greek\">εἰ</span>. <span class=\"greek\">ὑμῖν</span>, «paz a vós» = <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">שָׁלוֹם</bdi> <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">לָכֶם</bdi> (cf. Jz 6:23; 19:20; Dn 10:19, Teodócio; Tb 12:17), Lc 24:36; Jo 20:19, 21, 26; <span class=\"greek\">εἰρήνη τῷ οἴκῳ τούτῳ</span>, «paz a esta casa», Lc 10:5; cf. versículo 6 (W. Klassen, NTS 27, 1981, 488–506); Mt 10:12, variante, 13 (sobre <span class=\"greek\">εἰ</span>. <span class=\"greek\">ἐπί</span> com acusativo, cf. Is 9:7; Sl 84:9). No encerramento epistolar: <span class=\"greek\">καὶ ἔστω μεθ</span>’ <span class=\"greek\">ὑμῶν εἰρήνη</span>, «seja convosco a paz», AcPlCor 2:40.</p>\n<p>Desenvolvimento novo e característico é a associação da saudação epistolar grega <span class=\"greek\">χαίρειν</span> com uma expressão hebraica, nas cartas paulinas e pós-paulinas: <span class=\"greek\">χάρις καὶ εἰρήνη</span>, «graça e paz» (veja <span class=\"greek\">χάρις</span> ②ⓒ), Rm 1:7; 1Co 1:3; 2Co 1:2; Gl 1:3; Ef 1:2; Fp 1:2; Cl 1:2; 1Ts 1:1; 2Ts 1:2; Tt 1:4; Fm 3; Ap 1:4. Com <span class=\"greek\">χάρις</span>, <span class=\"greek\">ἔλεος</span>, <span class=\"greek\">εἰρήνη</span>, «graça, misericórdia e paz», 1Tm 1:2; 2Tm 1:2; 2Jo 3. <span class=\"greek\">χάρις καὶ εἰ</span>. (ou com <span class=\"greek\">ἔλεος</span>) <span class=\"greek\">πληθυνθείη</span>, «multipliquem-se graça e paz» (cf. Dn 4:1; 4:37c, LXX; 6:26, Teodócio), 1Pe 1:2; 2Pe 1:2; Jd 2; 1Cl, inscrição; Pol, inscrição; MPol, inscrição; cf. Gl 6:16; Ef 6:23; 2Ts 3:16; 1Pe 5:14; 3Jo 15; ISm 12:2; B 1:1 (<span class=\"greek\">χαίρετε ἐν εἰ</span>., «alegrai-vos em paz»). Até certo ponto, essa fórmula também implica a acepção ②ⓑ.</p>\n<p><strong>ⓑ Visto que, segundo os profetas, a paz será característica essencial do Reino messiânico</strong> (<span class=\"greek\">εἰ</span>. como *summum bonum*: Sêneca, Ep. 66, 5), o pensamento cristão frequentemente considera <span class=\"greek\">εἰ</span>. quase sinônimo de <strong>salvação messiânica</strong>. <span class=\"greek\">εὐαγγελίζεσθαι εἰ</span>., «anunciar a paz», isto é, a salvação messiânica (Is 52:7), At 10:36; Rm 10:15, variante; Ef 2:17; <span class=\"greek\">τὸ εὐαγγέλιον τῆς εἰ</span>., «o evangelho da paz», Ef 6:15; <span class=\"greek\">ἔχειν ἐν Χριστῷ εἰ</span>., «ter paz em Cristo», Jo 16:33; <span class=\"greek\">ἔχειν εἰ</span>. <span class=\"greek\">πρὸς τὸν θεόν</span>, «ter paz com Deus», Rm 5:1 (sobre <span class=\"greek\">εἰ</span>. <span class=\"greek\">πρός τινα</span>, cf. Platão, Rep. 5, 465b; Xenofonte, Hiero 2, 11; Epicteto 4, 5, 24; Josefo, Ant. 8, 396).</p>\n<p><span class=\"greek\">ἀφιέναι εἰ</span>. <span class=\"greek\">τινί</span>, «deixar a paz a alguém», Jo 14:27a (cf. Orígenes, C. Cels. 8, 14, 20); no mesmo sentido, <span class=\"greek\">εἰ</span>. <span class=\"greek\">διδόναι</span>, «dar ou conceder a paz», Jo 14:27b; 2Ts 3:16b (assim Is 26:12; desde Tucídides 4, 19, 1; 21, 1, <span class=\"greek\">εἰ</span>. <span class=\"greek\">διδόναι</span> refere-se à concessão de paz política). Daí <span class=\"greek\">εἰ</span>. <span class=\"greek\">τοῦ Χριστοῦ</span>, «a paz trazida por Cristo», Cl 3:15; <span class=\"greek\">εἰ</span>. <span class=\"greek\">τοῦ θεοῦ</span>, «a paz de Deus», Fp 4:7; <span class=\"greek\">ὁ θεὸς τῆς εἰ</span>., «o Deus da paz» (TestDan 5:2), Rm 15:33; 16:20; 2Co 13:11; Fp 4:9; 1Ts 5:23; Hb 13:20; <span class=\"greek\">ὁ κύριος τῆς εἰ</span>., «o Senhor da paz», 2Ts 3:16a; <span class=\"greek\">αὐτός</span>, isto é, <span class=\"greek\">ὁ Χριστός</span>, <span class=\"greek\">ἐστιν ἡ εἰρήνη ἡμῶν</span>, «ele próprio [Cristo] é a nossa paz», Ef 2:14 (cf. POxy 41, 27, onde um funcionário é chamado <span class=\"greek\">εἰρήνη πόλεως</span>, «paz da cidade»; semelhantemente <span class=\"greek\">ἐπὶ τῆς εἰρήνης</span>, PAchm 7, 8; 104; F. Coggan, ET 53, 1942, 242 [oferta de paz], mas veja N. Snaith, ibid. 325s.).</p>\n<p><span class=\"greek\">ἐπαναδράμωμεν ἐπὶ τὸν τῆς εἰ</span>. <span class=\"greek\">σκοπόν</span>, «corramos em direção ao objetivo da paz», 1Cl 19:2; 2Pe 3:14; com <span class=\"greek\">ζωή</span>, «vida», Rm 8:6; com <span class=\"greek\">δόξα</span> e <span class=\"greek\">τιμή</span>, «glória e honra», 2:10; com <span class=\"greek\">δικαιοσύνη</span> e <span class=\"greek\">χαρά</span>, «justiça e alegria» (com <span class=\"greek\">χαρά</span>, En 5:9; Fílon, Leg. All. 1, 45), 14:17; 15:13; com <span class=\"greek\">πίστις</span>, <span class=\"greek\">φόβος</span>, <span class=\"greek\">ὑπομονή</span>, <span class=\"greek\">μακροθυμία</span>, «fé, temor, perseverança, longanimidade», 1Cl 64:1; <span class=\"greek\">παιδεία εἰηρήνης ἡμῶν ἐπ</span>’ <span class=\"greek\">αὐτόν</span>, «a disciplina que nos trouxe a paz estava sobre ele», 1Cl 16:5 (Is 53:5). Numa oração: <span class=\"greek\">εἰς ἀγαθὰ ἐν εἰ</span>., «em direção às coisas boas, em paz», 1Cl 60:3. Provavelmente se incluem aqui também Lc 2:29 e a saudação angélica <span class=\"greek\">ἐπὶ γῆς εἰ</span>., «paz na terra», 2:14; cf. 19:38.</p>\n<p>Quanto à paz como dom de Deus, cf. Epicteto 3, 13, 12: <span class=\"greek\">εἰρήνη ὑπὸ τοῦ θεοῦ κεκηρυγμένη διὰ τοῦ λόγου</span>, «paz proclamada por Deus mediante a razão [= filosofia]»; Enômao, em Eusébio, PE 5, 26, 5: a tarefa das divindades seria estabelecer e promover <span class=\"greek\">εἰρήνη</span> e <span class=\"greek\">φιλία</span>, «paz e amizade»; cf. as autoproclamações de Ísis em expressões correlatas, IAndrosIsis, Cime.</p>\n<p>— H. Fuchs, Augustin und der antike Friedensgedanke, 1926, 39–43; 167–223; W. Nestle, Der Friedensgedanke in der antiken Welt: Philol. Suppl. 31, 1938; W. van Leeuwen, Eirene in het NT, 1940; F. Bammel, Die Religionen der Welt und der Friede auf Erden, 1957; sobre a história da palavra, K. Brugmann e B. Keil, <span class=\"greek\">Εἰρήνη</span>: Berichte der Sächsischen Gesellschaft der Wissenschaften 68, 1916, n.os 3 e 4; G. Köstner, <span class=\"greek\">Εἰρήνη</span> in den Briefen des hl. Apostels, dissertação, Roma, 1958; W. Eisenbeis, Die Wurzel <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">שׁלם</bdi> im AT, Beihefte ZAW 113, 1969; RAC VIII 434–505 (bibliografia). — B. 1376. DELG. M-M. EDNT. TW. Spicq. Sv.</p></div></section></article> <article id=\"entry-eirenikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰρηνικός, ή, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirēnikós⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Xenofonte, Platão e outros; POxy 1033, 5; LXX; EpArist 273; Fílon, Spec. Leg. 1, 224 e outros; TestGad 6:2; Justino, D. 131, 5; Ath. 1, 2.) <strong>Referente àquilo que favorece uma relação harmoniosa; pacífico, propício à paz.</strong> <span class=\"greek\">ἄνθρωπος εἰ</span>., «homem pacífico», 1Cl 14:5 (Sl 36:37). Da sabedoria (<span class=\"greek\">σοφία</span>) cristã, Tg 3:17. <span class=\"greek\">καρπὸν εἰ</span>. <span class=\"greek\">ἀποδιδόναι</span>, «produzir fruto pacífico», Hb 12:11. — DELG, s.v. <span class=\"greek\">εἰρήνη</span>. M-M. TW. Spicq.</p></div></section></article> <article id=\"entry-eirenopoieo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰρηνοποιέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirēnopoiéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Primeiro aoristo <span class=\"greek\">εἰρηνοποίησα</span> (LXX, Pv 10:10; Áquila, Símaco, Teodócio, Is 27:5; Cat. Cod. Astr. II 203; voz média, Herm. Wr. I, p. 498, 10 Sc.). <strong>Promover uma relação correta ou harmoniosa; fazer a paz</strong>, Cl 1:20. — DELG, s.v. <span class=\"greek\">εἰρήνη</span>. TW.</p></div></section></article> <article id=\"entry-eirenopoios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰρηνοποιός, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirēnopoiós⟧</span><span class=\"separator\">·</span><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Xenofonte, Hell. 6, 3, 4; Cornuto 16, p. 23, 2; Cássio Díon 44, 49, 2; 73, 15, 5: <span class=\"greek\">εἰρ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκουμένης</span>, «pacificador do mundo habitado»; Plutarco, Mor. 279b; Pólux 152; PSI 1036, 28 [192 d.C.]; Fílon, Spec. Leg. 2, 192; Cat. Cod. Astr. IX/2, p. 171, 19, juntamente com <span class=\"greek\">ἥμερος</span>, «manso».) <strong>Referente a quem procura reconciliar pessoas em desacordo; promotor da paz.</strong> Cf. *omnia animalia … pacifica … fieri*, «todos os animais se tornam pacíficos», Papias (1:3). Substantivado <span class=\"greek\">ὁ εἰ</span>., «o pacificador», Mt 5:9 (H. Windisch, Friedensbringer—Gottessöhne, ZNW 24, 1925, 240–260). — DELG, s.v. <span class=\"greek\">εἰρήνη</span>. TW. Spicq.</p></div></section></article> <article id=\"entry-eirusmai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴρυσμαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eírysmai⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">ῥύομαι</span>.</p></div></section></article> <article id=\"entry-eironeia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰρωνεία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eirōneía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Platão e outros; 2Mac 13:3.) <strong>«Ignorância fingida»</strong>, usada para embaraçar um adversário no debate por meio de afirmações que dizem menos do que se pensa (Platão, Rep. 337a e outros); daí, <strong>dissimulação, fingimento, afetação</strong> (cf. Aristóteles, EN 2, 7, 12): <span class=\"greek\">τῆς νηστείας</span>, «jejum fingido, ostentado», Dg 4:1. — W. Büchner, Hermes 76, 1941, 339–358; Reader, Polemo 256; DELG, s.v. <span class=\"greek\">εἴρων</span>.</p></div></section></article> <article id=\"entry-eis-preposition-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eis⟧</span><span class=\"separator\">·</span><span>preposição com acusativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Preposição com acusativo (Homero e seguintes; veja a bibliografia no início de <span class=\"greek\">ἀνά</span>; também A. Theimer, Die Präpositionen <span class=\"greek\">εἰς</span>, <span class=\"greek\">ἐν</span>, <span class=\"greek\">ἐκ</span> im NT: Programm zum 24. und 29. Jahresbericht des niederösterreichischen Landes-Real- und Obergymnasiums Horn, 1896; 1901; A. Oepke, TW II 418–432). Indica movimento para o interior de alguma coisa, para sua proximidade imediata ou para uma relação com algo.</p>\n<p><strong>① Extensão que envolve objetivo ou lugar; para dentro de, em, em direção a, para.</strong></p>\n<p><strong>ⓐ Para dentro de, em direção a, para</strong>, depois de verbos de ir ou de verbos que incluem movimento em direção a algum lugar (também depois de substantivos, como <span class=\"greek\">ἄφιξις</span>, «chegada», Taciano 37, 1, ou <span class=\"greek\">πορεία</span>, «trajeto», 38, 1). Assim após <span class=\"greek\">ἄγω</span>, <span class=\"greek\">ἀκολουθέω</span>, <span class=\"greek\">ἀναβαίνω</span>, <span class=\"greek\">ἀνάγω</span>, <span class=\"greek\">ἀναχωρέω</span>, <span class=\"greek\">ἀνέρχομαι</span>, <span class=\"greek\">ἄπειμι</span>, <span class=\"greek\">ἀπέρχομαι</span>, <span class=\"greek\">ἀποδημέω</span>, <span class=\"greek\">ἀποπλέω</span>, <span class=\"greek\">γίνομαι δεῦρο</span>, <span class=\"greek\">διαβαίνω</span>, <span class=\"greek\">διαπεράω</span>, <span class=\"greek\">διασῴζω</span>, <span class=\"greek\">διέρχομαι</span>, <span class=\"greek\">διώκω</span>, <span class=\"greek\">εἰσάγω</span>, <span class=\"greek\">εἴσειμι</span>, <span class=\"greek\">εἰσέρχομαι</span>, <span class=\"greek\">εἰσπορεύομαι</span>, <span class=\"greek\">ἐκπηδάω</span>, <span class=\"greek\">ἐκπλέω</span>, <span class=\"greek\">ἐκπορεύομαι</span>, <span class=\"greek\">ἐμβαίνω</span>, <span class=\"greek\">ἐμβάλλω</span>, <span class=\"greek\">ἐνδύνω</span>, <span class=\"greek\">ἐξέρχομαι</span>, <span class=\"greek\">ἐπανάγω</span>, <span class=\"greek\">ἐπιβαίνω</span>, <span class=\"greek\">ἐπιστρέφω</span>, <span class=\"greek\">ἔρχομαι</span> (veja Goodspeed, Problems, 56s.), <span class=\"greek\">εὐθυδρομέω</span>, <span class=\"greek\">ἥκω</span>, <span class=\"greek\">καθίζω</span>, <span class=\"greek\">καταβαίνω</span> (veja Goodspeed, Problems, 52–54), <span class=\"greek\">κατάγομαι</span>, <span class=\"greek\">καταντάω</span>, <span class=\"greek\">καταπλέω</span>, <span class=\"greek\">καταφεύγω</span>, <span class=\"greek\">κατέρχομαι</span>, <span class=\"greek\">μεταβαίνω</span>, <span class=\"greek\">ὁρμάω</span>, <span class=\"greek\">παραβάλλω</span>, <span class=\"greek\">παραγίνομαι</span>, <span class=\"greek\">πέτομαι</span>, <span class=\"greek\">πλέω</span>, <span class=\"greek\">πορείαν ποιοῦμαι</span>, <span class=\"greek\">πορεύομαι</span>, <span class=\"greek\">προάγω</span>, <span class=\"greek\">συμβάλλω</span>, <span class=\"greek\">συνάγομαι</span>, <span class=\"greek\">συναναβαίνω</span>, <span class=\"greek\">συνέρχομαι</span>, <span class=\"greek\">ὑπάγω</span>, <span class=\"greek\">ὑποστρέφω</span>, <span class=\"greek\">ὑποχωρέω</span>, <span class=\"greek\">φεύγω</span>, <span class=\"greek\">χωρέω</span>; veja os respectivos verbetes.</p>\n<p><strong><span class=\"greek\">α</span>. Extensão para um lugar específico a ser alcançado.</strong> Por isso, com substantivos que designam lugares acessíveis: <span class=\"greek\">εἰς τὸν οἶκον</span>, «para dentro da casa», Mt 9:7; sinagoga, At 17:10; céu, Lc 2:15; abismo, 8:31. <span class=\"greek\">φεύγειν εἰς τὰ ὄρη</span>, «fugir para os montes», Mc 13:14. Com nomes de localidades e países, «para a Espanha», Rm 15:24, 28; <span class=\"greek\">εἰς Ἰερουσαλήμ</span>, «para Jerusalém», versículo 25 e outros. Também «sobre, em»: <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὰς</span>) <span class=\"greek\">ὁδούς</span>, «pelas estradas», Lc 14:23; Mt 10:5, 10; <span class=\"greek\">εἰς ὁδόν</span>, «para o caminho», Mc 6:8; 10:17; <span class=\"greek\">εἰς ἀγρόν</span>, «para o campo», 16:12. Noutro sentido, <span class=\"greek\">ἀναβαίνει εἰς τὸ ὄρος</span>, «sobe ao monte», Mc 3:13; Mt 15:29.</p>\n<p>«Nas proximidades de, perto de, até»: (Josefo, Vi. 115: <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">κώμην</span>, «até a aldeia»), <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">θάλασσαν</span>, «para o mar, junto ao mar», Mc 7:31; 3:7, variante; Mt 17:27. <span class=\"greek\">εἰς πόλιν</span>, «até uma cidade» (Heródoto 2, 169; 4, 200, 1; Diodoro Sículo 15, 32, 2: <span class=\"greek\">παραγενόμενος εἰς πόλιν</span>), Jo 4:5; cf. versículo 28. <span class=\"greek\">εἰς τό μνημεῖον</span>, «ao sepulcro», Jo 11:31, 38; 20:1, 3s. (cf. versículo 6); <span class=\"greek\">ἐγγίζειν εἰς</span>, «aproximar-se de» (Tb 11:1), Mt 21:1; Mc 11:1; Lc 18:35; 19:29; <span class=\"greek\">εἰς τοὺς φραγμούς</span>, «até as cercas», Lc 14:23; <span class=\"greek\">κλίνειν τὸ πρόσωπον εἰς τ</span>. <span class=\"greek\">γῆν</span>, «inclinar o rosto para a terra», Lc 24:5.</p>\n<p><strong><span class=\"greek\">β</span>. Com enfoque na região dentro do ponto alcançado.</strong> Depois de verbos de enviar, deslocar etc., que provocam movimento ou incluem deslocamento corporal «para, para dentro de, entre»: <span class=\"greek\">εἰς τὴν πόλιν</span>, «para dentro da cidade», Mt 26:18 e outros; barco, Mt 8:23; Jo 6:17; mundo, Jo 1:9; <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">ναόν</span>, «para dentro do templo», 2Ts 2:4; <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">μέσον</span>, «para o meio» (Sir 27:12; cf. 48:17): <span class=\"greek\">ἔστη εἰς τὸ μέσον</span> (Xenofonte, Cyr. 4, 1, 1), «[ele veio e] pôs-se no meio deles», Jo 20:19, 26; cf. Mc 14:60; Lc 6:8; também <span class=\"greek\">ἔγειρε εἰς τὸ μ</span>., «levanta-te e vem para o meio», Mc 3:3. — <span class=\"greek\">δέχεσθαι εἰς τὰς ἀγκάλας</span>, «receber nos braços», Lc 2:28 (cf. Josefo, Ant. 8, 28).</p>\n<p><strong><span class=\"greek\">γ</span>. Movimento dirigido à superfície de uma região; sobre, em.</strong> Referente a golpes (PRyl 145, 13s. [38 d.C.]: <span class=\"greek\">ἔδωκεν πληγὰς πλείους εἰς πᾶν μέρος τοῦ σώματος</span>, «desferiu muitos golpes por todo o corpo»; cf. PTebt 39, 32): <span class=\"greek\">τύπτειν εἰς τ</span>. <span class=\"greek\">κεφαλήν</span>, «bater na cabeça», Mt 27:30 (cf. Arriano, Anab. 2, 26, 4: <span class=\"greek\">ἐμβάλλειν εἰς τ</span>. <span class=\"greek\">κεφαλήν</span>). <span class=\"greek\">ῥαπίζειν εἰς τὴν σιαγόνα</span>, «esbofetear na face», Mt 5:39; <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">ὄμματα</span>, «nos olhos», Mc 8:23; <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">ὁδόν</span>, «no caminho», 11:8; <span class=\"greek\">ἀναπίπτειν εἰς τ</span>. <span class=\"greek\">ἔσχατον τόπον</span>, «sentar-se no lugar mais baixo», Lc 14:10; cf. versículo 8; <span class=\"greek\">εἰς τὴν χεῖρα</span>, <span class=\"greek\">τοὺς πόδας</span>, «na mão, nos pés», Lc 15:22.</p>\n<p><strong><span class=\"greek\">δ</span>. Posição dentro de determinada área; estar em, estar sobre.</strong> <span class=\"greek\">εἰς</span> frequentemente é empregado onde se esperaria <span class=\"greek\">ἐν</span> (veja ①ⓑ<span class=\"greek\">β</span> abaixo; sobre Marcos, J. O’Rourke, JBL 85, 1966, 349–351; Heródoto 7, 239, 1; Diodoro Sículo 13, 101, 3; 20, 30, 2; Vettius Valens, índice III, p. 394b; PTebt 38, 14 [113 a.C.]: <span class=\"greek\">εἰς ὸ̔ν ἐνοικεῖ</span> … <span class=\"greek\">οἶκον</span>, «na casa que habita»; POxy 294, 6 [22 d.C.]; 929, 12; BGU 385, 5; 423, 7; Kaibel 134; LXX; G. Hatzidakis, Einleitung in die neugriechische Grammatik, 1892, 210s.; Mlt. 62s., 234s.; Rob. 592s.; Rdm.² 14, 140; B-D-F §205; E. Oldenburger, De Oraculorum Sibyllinorum Elocutione, dissertação, Rostock, 1903, 26ss.).</p>\n<p><span class=\"greek\">εἰς τ</span>. <span class=\"greek\">κοίτην εἶναι</span>, «estar na cama», Lc 11:7; <span class=\"greek\">εἰς τὴν οἰκίαν</span>, «na casa», Mc 10:10; <span class=\"greek\">οἱ εἰς τ</span>. <span class=\"greek\">οἶκόν μου</span> (<span class=\"greek\">ὄντες</span>), «os que estão em minha casa», Lc 9:61; <span class=\"greek\">οἱ εἰς μακρὰν</span> (<span class=\"greek\">ὄντες</span>), «os que estão longe», At 2:39; <span class=\"greek\">καθημένου εἰς τὸ ὄρος</span>, «estando sentado no monte», Mc 13:3 (cf. Musônio 43, 18 H.: <span class=\"greek\">καθῆσθαι εἰς Σινώπην</span>, «residir em Sinope»); <span class=\"greek\">ὁ εἰς τὸν ἀγρὸν</span> (<span class=\"greek\">ὤν</span>), «aquele que está no campo», Mc 13:16; <span class=\"greek\">γίνεσθαι εἰς τὴν Καφαρναούμ</span>, «acontecer em Cafarnaum», Lc 4:23; <span class=\"greek\">εἰς συναγωγὰς δαρήσεσθε</span>, «sereis açoitados nas sinagogas», Mc 13:9; <span class=\"greek\">εὑρέθη εἰς Ἄζωτον</span>, «encontrou-se em Azoto», At 8:40 (cf. Est 1:5: <span class=\"greek\">τοῖς ἔθνεσιν τοῖς εὑρεθεῖσιν εἰς τ. πόλιν</span>, «aos povos que se encontravam na cidade»; Gn 37:17); <span class=\"greek\">ἀποθανεῖν εἰς Ἰερ</span>., «morrer em Jerusalém», At 21:13 (cf. Eliano, VH 7, 8: <span class=\"greek\">Ἡφαιστίων εἰς Ἐκβάτανα ἀπέθανε</span>, «Heféstion morreu em Ecbátana»); <span class=\"greek\">κατοικεῖν εἰς Ἰερ</span>., «habitar em Jerusalém», At 2:5; cf. Mt 2:23; 4:13; At 7:4; Hb 11:9 (cf. Tucídides 2, 102, 6; Xenofonte, An. 1, 2, 24; Nm 35:33; 2Cr 19:4).</p>\n<p><span class=\"greek\">χάριν</span>, <span class=\"greek\">εἰς ἣν στῆτε</span>, «graça na qual permaneceis», 1Pe 5:12; <span class=\"greek\">ἔχειν βιβλίον εἰς τὰς χεῖρας</span>, «ter um livro nas mãos», Hv 1, 2, 2; <span class=\"greek\">πηλὸς γάρ ἐσμεν εἰς την χεῖρα τοῦ τεχνίτου</span>, «pois somos barro nas mãos do artesão»; <span class=\"greek\">εἰς ταύτην τὴν πόλιν</span>, «nesta cidade», Hv 2, 4, 3 e outros. <span class=\"greek\">εἰς</span> também equivale a «em, sobre» (BGU 845, 20s.; TestJob 25:5: <span class=\"greek\">τραπέζας</span> … <span class=\"greek\">εἰς ἃς ἤσθιον οἱ πτωχοί</span>, «mesas nas quais comiam os pobres»): <span class=\"greek\">ὁ ὢν εἰς τ</span>. <span class=\"greek\">κόλπον τ</span>. <span class=\"greek\">πατρός</span>, «aquele que está no seio do Pai» (ou «reclinado em seu colo»; isto é, que mantém íntima relação com o Pai; veja <span class=\"greek\">κόλπος</span>), Jo 1:18. Em AcPlCor 2:35, as preposições <span class=\"greek\">εἰς</span> e <span class=\"greek\">ἐν</span> parecem cuidadosamente distintas: <span class=\"greek\">τὰ δεσμὰ εἰς τὰς χείρας ἔχω</span> … <span class=\"greek\">καὶ τὰ στίγματα ἐν τῷ σώματί μου</span>, «trago as algemas nas mãos… e as marcas no corpo».</p>\n<p><strong><span class=\"greek\">ε</span>. Presença numa área determinada por outros objetos</strong>, sobretudo após verbos de enviar, deslocar etc., incluindo <span class=\"greek\">ἀπολύω</span>, <span class=\"greek\">ἀποστέλλω</span>, <span class=\"greek\">βάλλω</span>, <span class=\"greek\">βαπτίζω</span>, <span class=\"greek\">δέχομαι</span>, <span class=\"greek\">δίδωμι</span>, <span class=\"greek\">ἐγκεντρίζω</span>, <span class=\"greek\">ἐκβάλλω</span>, <span class=\"greek\">ἐκπέμπω</span>, <span class=\"greek\">ἐκχέω</span>, <span class=\"greek\">ἐμβάπτω</span>, <span class=\"greek\">ἐξαποστέλλω</span>, <span class=\"greek\">καθίημι</span>, <span class=\"greek\">μεταπέμπομαι</span>, <span class=\"greek\">παρακύπτω</span>, <span class=\"greek\">πέμπω</span>, <span class=\"greek\">χαλάω</span>; veja os verbetes respectivos. <span class=\"greek\">ἐμπίπτειν εἰς τοὺς λῃστάς</span>, «cair entre salteadores», Lc 10:36; <span class=\"greek\">εἰς τὰς ἀκάνθας</span>, «entre os espinhos», Mc 4:7; <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">λαόν</span>, «entre o povo», At 4:17 e outros, em que a tradução depende do verbo. <span class=\"greek\">πνεύματος ἁγίου</span> … <span class=\"greek\">ἀποσταλέντος εἰς αὐτήν</span> (<span class=\"greek\">Μαρίαν</span>), «o Espírito Santo… enviado para dentro dela [Maria]», AcPlCor 2:5; cf. 2:10: <span class=\"greek\">ἔπεμψεν εἰς τοὺς προφήτας</span>, «enviou para dentro dos profetas»; 2:14: <span class=\"greek\">κατέπεμψε</span> … <span class=\"greek\">εἰς Μαρίαν</span>, «enviou para Maria». <span class=\"greek\">ἔστη εἰς τὸ κριτήριον</span>, «ela se pôs diante do tribunal», GJs 15:2 (diferente de Jo 20:19, 26; veja ①ⓐ<span class=\"greek\">β</span>).</p>\n<p><strong>ⓑ Direção a alguma coisa sem referência a movimento corporal. <span class=\"greek\">α</span>. Com verbos de olhar</strong> (desde Od. 10, 37; Il. 3, 364; LXX): <span class=\"greek\">ἀναβλέπειν εἴς τι</span>, «levantar o olhar para algo» (2Mac 7:28; Sus 35, Teodócio), Mc 6:41; Lc 9:16; At 22:13; cf. <span class=\"greek\">ἀτενίζω</span>, <span class=\"greek\">βλέπω</span>, <span class=\"greek\">ἐμβλέπω</span>, <span class=\"greek\">ὁράω</span> (Justino, D. 112, 1). — <span class=\"greek\">ἐπαίρειν τοὺς ὀφθαλμοὺς εἴς τινα</span>, «levantar os olhos para alguém», Lc 6:20.</p>\n<p><strong><span class=\"greek\">β</span>. Depois de verbos de falar, ensinar, anunciar e pregar</strong> (trágicos; Heródoto 8, 26, 3; Tucídides 1, 72, 2; 5, 45, 1 e muitos autores posteriores, inclusive a LXX): <span class=\"greek\">λαλεῖν εἰς τ</span>. <span class=\"greek\">κόσμον</span>, «falar ao mundo», Jo 8:26; <span class=\"greek\">τὸ εὐαγγέλιον εἰς ὅλον τ</span>. <span class=\"greek\">κόσμον</span>, «o evangelho por todo o mundo», Mc 14:9; <span class=\"greek\">εἰς πάντα τὰ ἔθνη</span>, «a todas as nações», 13:10; Lc 24:47; <span class=\"greek\">εἰς ὑμᾶς</span>, «a vós», 1Ts 2:9; <span class=\"greek\">εὐαγγελίζεσθαι εἴς τινα</span>, «anunciar o evangelho a alguém», 2Co 10:16; 1Pe 1:25; <span class=\"greek\">γνωρίζειν</span>, «dar a conhecer», Rm 16:26; <span class=\"greek\">ἀπαγγέλλειν τι εἴς τινα</span>, «noticiar algo a alguém», Mc 5:14; Lc 8:34; <span class=\"greek\">διαμαρτύρεσθαι εἰς Ἰερουσαλήμ</span>, <span class=\"greek\">μαρτυρεῖν εἰς Ῥώμην</span>, «dar testemunho em Jerusalém, em Roma», At 23:11; <span class=\"greek\">ἵνα εἰς Νινευὴ μὴ κηρύξῃ</span>, «para que não pregue em Nínive», AcPlCor 2:29. Nesses casos e semelhantes, <span class=\"greek\">εἰς</span> aproxima-se de <span class=\"greek\">ἐν</span> quanto ao sentido; veja ①ⓐ<span class=\"greek\">δ</span>.</p>\n<p><strong><span class=\"greek\">γ</span>. O mesmo ocorre com</strong> <span class=\"greek\">βαπτίζεσθαι εἰς τὸν Ἰορδάνην</span>, «ser batizado no Jordão», Mc 1:9, e <span class=\"greek\">νίπτεσθαι εἰς τὴν κολυμβήθραν</span>, «lavar-se no tanque», Jo 9:7. Essas expressões parecem exemplos de alternância entre <span class=\"greek\">εἰς</span> e <span class=\"greek\">ἐν</span>, mas originalmente se formaram por analogia com Xenofonte, Cyr. 1, 3, 5: <span class=\"greek\">ἀποκαθαίρει τὴν χεῖρα εἰς τὰ χειρόμακτρα</span>, literalmente «limpa a mão nas toalhas»; cf. Epicteto 3, 22, 71: <span class=\"greek\">ἵν</span>’ <span class=\"greek\">αὐτὸ</span> (<span class=\"greek\">τὸ παιδίον</span>) <span class=\"greek\">λούσῃ εἰς σκάφην</span>, «para banhar a criança numa bacia»; Alcífron, Ep. 3, 7, 1; Ateneu 10, 438e.</p>\n<p><strong>② Extensão temporal; até, até que, em, para.</strong></p>\n<p><strong>ⓐ Com indicação de momento específico. <span class=\"greek\">α</span>. Até o qual algo continua:</strong> <span class=\"greek\">εἰς τέλος</span>, «até o fim» (Epicteto 1, 7, 17), Mt 10:22; 24:13; Mc 13:13. <span class=\"greek\">εἰς ἐκείνην τὴν ἡμέραν</span>, «até aquele dia», 2Tm 1:12 (Ath. 2, 1: <span class=\"greek\">εἰς</span> … <span class=\"greek\">τὴν σήμερον ἡμέραν</span>, «até o dia de hoje»). <span class=\"greek\">εἰς ἡμέραν Χριστοῦ</span>, «até o dia de Cristo», Fp 1:10; <span class=\"greek\">εἰς Χριστόν</span>, «até a vinda do Messias», Gl 3:24.</p>\n<p><strong><span class=\"greek\">β</span>. Para o qual ou no qual algo acontece:</strong> <span class=\"greek\">μεριμνᾶν εἰς τὴν αὔριον</span>, «preocupar-se com o amanhã», Mt 6:34; cf. Hs 6, 5, 3; <span class=\"greek\">εἰς τὸ μέλλον</span>, «para o futuro», 1Tm 6:19; <span class=\"greek\">εἰς τὸ μεταξὺ σάββατον</span>, «no sábado seguinte», At 13:42; <span class=\"greek\">εἰς ἡμέραν</span>, «para o dia» (UPZ 66, 5 [153 a.C.]), Fp 2:16; cf. Ef 4:30; Ap 9:15.</p>\n<p><strong><span class=\"greek\">γ</span>. No qual algo acontece:</strong> (Apiano, Mithrid. 74 §321: <span class=\"greek\">ἐς ἑσπέραν</span>, «à tarde»; Epicteto 4, 10, 31: <span class=\"greek\">αὔριον ἢ εἰς τὴν τρίτην</span>, «amanhã ou no terceiro dia»; En 1:1: <span class=\"greek\">οἵτινες ἔσονται εἰς ἡμέραν ἀνάγκης</span>, «que estarão presentes no dia da necessidade».) <span class=\"greek\">εἰς τὸν καιρὸν αὐτῶν</span>, «no seu devido tempo», Lc 1:20; <span class=\"greek\">εἰς τὸ μέλλον</span>, «no futuro», 13:9; <span class=\"greek\">εἰς τέλος</span>, «no fim, finalmente» (Heródoto 3, 403; Gn 46:4; Pseudo-Clemente, Hom. 18, 2), Lc 18:5 (B-D-F §207, 3 prefere a acepção ③ abaixo e <span class=\"greek\">ὑπωπιάζω</span> ③; veja também Mlt-Turner 266); <span class=\"greek\">εἰς τὸ πάλιν</span> = <span class=\"greek\">πάλιν</span>, «novamente», 2Co 13:2; veja Schmid I 167; II 129; III 282; IV 455, 625; <span class=\"greek\">εἰς ταχεῖαν</span>, «em breve», AcPlCor 2:3.</p>\n<p><strong>ⓑ Para indicar duração; por, durante</strong> (Nicolau de Damasco, fragmento 90 Fgm. 4, p. 332, 16 Jac.: <span class=\"greek\">εἰς νύκτα</span>, «durante a noite»; Arriano, Anab. 4, 30, 1: <span class=\"greek\">ἐς τρεῖς ἡμέρας</span>, «por três dias»; Justino, D. 2, 5: <span class=\"greek\">εἰς μακράν</span>, «por muito tempo»). <span class=\"greek\">εἰς ἔτη πολλά</span>, «por muitos anos», Lc 12:19. <span class=\"greek\">εἰς τὸν αἰῶνα</span>, <span class=\"greek\">εἰς τοὺς αἰῶνας</span>, «para sempre» (veja <span class=\"greek\">αἰών</span> ①ⓑ), Mt 21:19; Mc 3:29; 11:14; Lc 1:33; Jo 8:35 e frequentemente. <span class=\"greek\">εἰς ἡμέραν αἰῶνος</span>, «até o dia da eternidade», 2Pe 3:18; <span class=\"greek\">εἰς γενεὰς καὶ γενεάς</span>, «de geração em geração», Lc 1:50; <span class=\"greek\">εἰς τὸ διηνεκές</span>, «para sempre», Hb 7:3; 10:1, 12, 14 (cf. Tucídides 2, 64, 3: <span class=\"greek\">ἐς ἀί̈διον</span>, «perpetuamente»).</p>\n<p><strong>③ Indicador de grau; até, completamente.</strong> <span class=\"greek\">εἰς τέλος</span>, «completamente, plenamente, absolutamente» (veja Justino, A I, 44, 12 e <span class=\"greek\">τέλος</span> ②ⓑ<span class=\"greek\">γ</span>), 1Ts 2:16; B 4:7; 19:11; Hv 3, 7, 2; Hm 12, 2, 3; Hs 8, 6, 4; 8, 8, 5; 8, 9, 3. Jo 13:1 reúne em <span class=\"greek\">εἰς τέλος</span> os sentidos «até o fim» (②ⓐ<span class=\"greek\">α</span> acima) e «ao extremo» (cf. Apiano, Mithrid. 58 §239: <span class=\"greek\">ἡμῶν ἀμυναμένων ἤδη καὶ ἀμυνουμένων ἐς τέλος</span>, «defendemo-nos até agora e continuaremos a defender-nos até o fim»). <span class=\"greek\">εἰς τὰ ἄμετρα</span>, «além dos limites», 2Co 10:13, 15 (cf. PVat A 12 = Witkowski 36, 12 [168 a.C.]: <span class=\"greek\">εἰς τὰ ἔσχατα</span>, «até os extremos»); <span class=\"greek\">εἰς περισσείαν</span>, «em abundância», 2Co 10:15; <span class=\"greek\">εἰς ὑπερβολήν</span>, «em excesso, extraordinariamente» (Eurípides, Hipp. 939; Ésquines, F. Leg. 4), 2Co 4:17; <span class=\"greek\">εἰς τὸ παντελές</span> (veja <span class=\"greek\">παντελής</span> ②), «inteiramente», Lc 13:11; Hb 7:25 (Taciano 6, 1).</p>\n<p><strong>④ Indicador de objetivos que envolvem aspectos afetivos, abstratos ou de adequação; para dentro de, a, para.</strong></p>\n<p><strong>ⓐ Entrada num estado de existência</strong>, com verbos de ir, vir, conduzir etc., usados figuradamente: <span class=\"greek\">ἀπέρχεσθαι εἰς κόλασιν αἰώνιον</span>, «ir para castigo eterno», Mt 25:46 (cf. Sir 41:10); <span class=\"greek\">εἰσφέρειν εἰς πειρασμόν</span>, «introduzir em tentação», Mt 6:13; <span class=\"greek\">πορεύεσθαι εἰς θάνατον</span>, «ir para a morte», Lc 22:33; <span class=\"greek\">ὑπάγειν εἰς ἀπώλειαν</span>, «caminhar para a perdição», Ap 17:8, 11; <span class=\"greek\">βάλλειν εἰς θλῖψιν</span>, «lançar em tribulação», Ap 2:22; <span class=\"greek\">παραδιδόναι εἰς θλῖψιν</span>, «entregar à tribulação», Mt 24:9; cf. 2Co 4:11; Lc 24:20; <span class=\"greek\">συγκλείειν εἰς ἀπείθειαν</span>, «encerrar na desobediência», Rm 11:32; <span class=\"greek\">ἐμπίπτειν εἰς κρίμα</span>, «incorrer em juízo», 1Tm 3:6s.; cf. 6:9 (e Ath. 24, 5: <span class=\"greek\">εἰς ἐπιθυμίαν πεσόντες παρθένων</span>, «caindo no desejo por virgens»); <span class=\"greek\">ἄγειν εἰς μετάνοιαν</span>, «conduzir ao arrependimento», Rm 2:4; cf. Hb 2:10: <span class=\"greek\">εἰς δόξαν</span>, «à glória» (Justino, A I, 10, 4: <span class=\"greek\">εἰς πίστιν</span>, «à fé»; 42, 11: <span class=\"greek\">εἰς ἐπίστασιν καὶ ἀνάμνησιν</span>, «ao conhecimento e à recordação»); <span class=\"greek\">αἰχμαλωτίζειν εἰς ὑπακοήν</span>, «levar cativo à obediência», 2Co 10:5; <span class=\"greek\">ἀνακαινίζειν εἰς μετάνοιαν</span>, «renovar para o arrependimento», Hb 6:6; cf. 2:10. Semelhantemente com <span class=\"greek\">ἀπάγω</span>, <span class=\"greek\">ἀποβαίνω</span>, <span class=\"greek\">εἰσέρχομαι</span>, <span class=\"greek\">εἰσφέρω</span>, <span class=\"greek\">ἐκβάλλω</span>, <span class=\"greek\">ἐλευθερόω</span>, <span class=\"greek\">ἐπιστρέφω</span>, <span class=\"greek\">κατευθύνω</span>, <span class=\"greek\">μεταβαίνω</span>, <span class=\"greek\">ὁδηγέω</span> e outros; veja esses verbetes.</p>\n<p><strong>ⓑ Mudança de um estado para outro</strong>, com verbos de transformação: <span class=\"greek\">στρέφειν</span> (Est 4:17h; 1Mac 1:39), <span class=\"greek\">μεταστρέφειν</span> (Sir 11:31; 1Mac 9:41; 3Mac 6:22), <span class=\"greek\">τι εἴς τι</span>, «transformar algo em outra coisa», Ap 11:6; At 2:20 (Jl 3:4); Tg 4:9. <span class=\"greek\">μεταλλάσσειν</span>, «mudar, trocar», Rm 1:26; <span class=\"greek\">μετασχηματίζεσθαι</span> (veja este verbo ②), 2Co 11:13s.; <span class=\"greek\">μετατίθεσθαι εἰς</span>, «desviar-se para», Gl 1:6.</p>\n<p><strong>ⓒ Ações ou sentimentos dirigidos a alguém, em sentido hostil ou amistoso</strong> (Tucídides 1, 38; 66; 130; Xenofonte, Cyr. 1, 3, 5; Pausânias 7, 9, 3; 7, 10, 2; Eliano, VH 11, 10).</p>\n<p><strong><span class=\"greek\">α</span>. Em sentido hostil</strong> (Arriano, Anab. 1, 1, 4; PEleph 1, 9 [311/310 a.C.]: <span class=\"greek\">κακοτεχνεῖν εἰς Δημητρίαν</span>, «maquinar contra Demétria»; UPZ 170b, 47 [127 a.C.]): <span class=\"greek\">ἁμαρτάνειν εἴς τινα</span>, «pecar contra alguém» (Herodiano 7, 9, 11; EpJer 12; Jd 5:20; 11:10), Lc 15:18, 21; <span class=\"greek\">βλασφημεῖν εἴς τινα</span>, «difamar, blasfemar contra alguém» (Bel 8, Teodócio; Justino, D. 122, 2), Mc 3:29; Lc 12:10; 22:65; <span class=\"greek\">θαρρεῖν εἴς τινα</span>, «mostrar ousadia diante de alguém», 2Co 10:1; <span class=\"greek\">ψεύδεσθαι εἴς τινα</span>, «mentir a alguém» (Sus 55; 59, Teodócio), Cl 3:9. Também com substantivos e adjetivos (Pausânias 7, 8, 4; PFay 12, 7 [cerca de 103 a.C.]: <span class=\"greek\">ἀδικήματα εἴς με</span>, «ofensas contra mim»; En 97:7: <span class=\"greek\">μνημόσυνον εἰς ὑμᾶς κακόν</span>, «memória maléfica contra vós»), At 6:11; 23:30; Rm 8:7.</p>\n<p><strong><span class=\"greek\">β</span>. Em sentido amistoso:</strong> <span class=\"greek\">μακροθυμεῖν</span>, «mostrar paciência para com», 2Pe 3:9; <span class=\"greek\">τὸ αὐτὸ φρονεῖν</span>, «pensar da mesma maneira acerca de», Rm 12:16; também <span class=\"greek\">πιστεύειν εἴς τινα</span>, «confiar em alguém, crer em alguém», Mt 18:6; Mc 9:42 e frequentemente (veja <span class=\"greek\">πιστεύω</span> ①ⓐ<span class=\"greek\">ε</span>). Também com substantivos (OGI 49, 10 [século III a.C.]: <span class=\"greek\">φιλοτιμία εἰς</span>, «benevolência para com»; 51, 4; UPZ 22, 18 [162 a.C.]; 39, 5: <span class=\"greek\">εἰς τὸ θεῖον εὐσέβεια</span>, «piedade para com a divindade»; 2Mac 9:26: <span class=\"greek\">εὔνοια</span>, «boa vontade»; Taciano 16:2: <span class=\"greek\">τῆς εἰς αὐτοὺς</span> [<span class=\"greek\">δαίμονας</span>] <span class=\"greek\">θρησκείας</span>, «o culto prestado a eles [os demônios]»): <span class=\"greek\">ἀγάπη</span>, «amor», Rm 5:8; 2Co 2:4, 8; Cl 1:4; 1Ts 3:12; <span class=\"greek\">ἐλπίς</span>, «esperança» (2Mac 9:20; Sinésio, Ep. 104, p. 264a: <span class=\"greek\">εἰς τὸν κομήτην ἐλπίς</span>, «esperança no conde»), At 24:15; <span class=\"greek\">κοινωνία</span>, «comunhão», Fp 1:5 (Taciano 18, 2); <span class=\"greek\">πεποίθησις</span>, «confiança», 2Co 8:22; <span class=\"greek\">δύναμις</span>, «poder», Ef 1:19; <span class=\"greek\">πίστις</span>, «fé» (Josefo, Ant. 16, 48; 18, 334), At 20:21; 24:24; 26:18; Cl 2:5; e adjetivos <span class=\"greek\">φιλόξενος</span>, «hospitaleiro», 1Pe 4:9; <span class=\"greek\">χρηστός</span>, «benigno», Ef 4:32; <span class=\"greek\">διακονία</span>, «serviço», Rm 15:31 (cf. a variante em At 12:25 e J. Dupont, NovT 1, 1956, 275–303); 2Co 8:4.</p>\n<p>O contexto de 1Pe 1:11 sugere consolação dos cristãos pelos sofrimentos suportados em ambiente hostil; daí a tradução da REB, «sofrimentos pela causa de Cristo». Para <span class=\"greek\">εἰς Χρ</span>. interpretado como genitivo (UPZ 180a II, 2 [113 a.C.]: <span class=\"greek\">χωρὶς τοῦ εἰς αὐτὴν οἴκου</span>, «sem a casa dela»; PTebt 16, 9s. contém restauração de <span class=\"greek\">εἰς</span>), veja a NRSV: «sofrimentos destinados a Cristo»; para expressão paralela em sentido hostil, cf. Políbio 1, 7, 12: <span class=\"greek\">τῆς εἰς ἐκείνους τιμωρίας</span>, «a punição contra eles»; 1, 69, 7; 38, 1 [4], 13; veja Kuhring 13 e Rudberg 201 (citados no início de <span class=\"greek\">ἀνά</span>).</p>\n<p><strong>ⓓ Com vocação, uso ou finalidade indicada; para, como.</strong> <span class=\"greek\">αἱρέομαι εἴς τι</span>, «escolher para», 2Ts 2:13; <span class=\"greek\">ἀφορίζω</span>, «separar para», Rm 1:1; At 13:2; <span class=\"greek\">προγράφω</span>, «escrever antecipadamente para», Rm 15:4; Jd 4; <span class=\"greek\">ἀποστέλλω</span>, «enviar para», Hb 1:14; <span class=\"greek\">πέμπω</span>, «enviar para», Fp 4:16; 1Ts 3:2, 5; <span class=\"greek\">ποιῶ τι εἰς</span>, «fazer algo para», 1Co 10:31; 11:24. Veja também <span class=\"greek\">κεῖμαι</span>, <span class=\"greek\">προορίζω</span>, <span class=\"greek\">τάσσω</span>, <span class=\"greek\">τίθημι</span>. <span class=\"greek\">εἰμὶ εἴς τι</span>, «servir como alguma coisa» (veja <span class=\"greek\">εἰμί</span> ⑥; também inscrição do Delfínion de Mileto 134, 33ss. [século I d.C.], publicada em 1914; Deissmann, LO 97, nota 1 [LAE 123]; Ar. 5, 1: <span class=\"greek\">ὕδωρ</span> … <span class=\"greek\">εἰς χρῆσιν τῶν ἀνθρώπων γέγονε</span>, «a água veio a existir para uso dos homens»), 1Co 14:22; «para destruição», Cl 2:22; «como testemunho», Tg 5:3.</p>\n<p>Com substantivo: <span class=\"greek\">σκεῦος εἰς τιμήν</span>, <span class=\"greek\">ἀτιμίαν</span>, «vaso destinado a uso honroso ou desonroso», Rm 9:21; cf. versículos 22s.; 2Tm 2:20s.; <span class=\"greek\">φύλλα τοῦ ξύλου εἰς θεραπείαν</span>, «folhas da árvore para cura», Ap 22:2; <span class=\"greek\">φῶς εἰς ἀποκάλυψιν</span>, «luz para servir de revelação», Lc 2:32; <span class=\"greek\">θεράπων εἰς μαρτύριον τῶν λαληθησομένων</span>, «servo para testemunhar as coisas que seriam ditas», Hb 3:5 (cf. Justino, A I, 66, 1: <span class=\"greek\">τὸ</span> … <span class=\"greek\">εἰς ἀναγέννησιν λουτρόν</span>, «o banho para regeneração»).</p>\n<p>Com acusativo de pessoa (Justino, A II, 12, 4: <span class=\"greek\">συκοφαντίᾳ τῇ εἰς ἡμᾶς</span>, «calúnia dirigida a nós»; Taciano 17, 3: <span class=\"greek\">τὴν εἰς τοὺς μεμηνότας βοήθειαν</span>, «a ajuda aos enlouquecidos»): <span class=\"greek\">ἡ εἰς ὑμᾶς χάρις</span>, «a graça destinada a vós», 1Pe 1:10. <span class=\"greek\">διδόναι εἴς τι</span>, «pagar por algo», dinheiro por um campo, Mt 27:10.</p>\n<p><strong>ⓔ Resultado de uma ação ou condição; para dentro de, a, de modo que.</strong> <span class=\"greek\">αὐξάνειν εἰς ναόν</span>, «crescer até tornar-se templo», Ef 2:21; <span class=\"greek\">πληροῦσθαι εἴς τι</span>, «ser preenchido até», Ef 3:19; <span class=\"greek\">λυπηθῆναι εἰς μετάνοιαν</span>, «entristecer-se de modo a produzir arrependimento», 2Co 7:9; acerca de oração, <span class=\"greek\">ἀναβαίνειν εἰς μνημόσυνον</span>, «subir como memorial», At 10:4; <span class=\"greek\">ὁμολογεῖν εἰς σωτηρίαν</span>, «confessar para salvação», isto é, a fim de receber a salvação, Rm 10:10; cf. 1:16; 1Pe 2:2; <span class=\"greek\">εἰς ἔπαινον κτλ</span>., «para louvor etc.», 1Pe 1:7; <span class=\"greek\">εἰς βοήθειαν</span>, «para auxílio» (1Cr 12:17; Jd 6:21; JosAs 23:4), Hb 4:16; cf. 10:39; Ap 13:3; Rm 6:16; 8:15; 13:4, 14; 1Co 11:34; 2Co 2:16 e outros; <span class=\"greek\">εἰς κενόν</span>, «em vão» (veja <span class=\"greek\">κενός</span> ③), 2Co 6:1; Gl 2:2; Fp 2:16; 1Ts 3:5; <span class=\"greek\">σχίζειν εἰς δύο</span>, «rasgar em dois», Mt 27:51; Mc 15:38. Cf. GPt 5:20 (Políbio 2, 16, 11; Luciano, Symp. 44; Tox. 54; 1Rs 15:29; Tb 5:3 S; 1Mac 9:11; Ath. 18, 3: <span class=\"greek\">ᾠὸν</span> … <span class=\"greek\">εἰς δύο ἐρράγη</span>, «o ovo… partiu-se em dois»). Seguido de infinitivo substantivado, «de modo que», Rm 1:20; 3:26; 4:18; 6:12; 7:4; 1Ts 3:13; 2Ts 2:10s.; Hb 11:3 e outros.</p>\n<p><strong>ⓕ Para indicar finalidade; a fim de, para</strong> (Apiano, Liby. 101 §476: <span class=\"greek\">ἐς ἔκπληξιν</span>, «para causar espanto»; Justino, A I, 21, 4: <span class=\"greek\">εἰς προτροπήν</span>, «para estimular»). <span class=\"greek\">εἰς ἄγραν</span>, «para apanhar [peixes]», Lc 5:4; <span class=\"greek\">εἰς ἀπάντησιν</span>, <span class=\"greek\">συνάντησιν</span>, <span class=\"greek\">ὑπάντησίν τινι</span>, «para encontrar alguém, ao encontro de» (veja esses três verbetes), Mt 8:34; 25:1; Jo 12:13; <span class=\"greek\">εἰς μαρτύριον αὐτοῖς</span>, «como testemunho», isto é, como prova para eles, Mt 8:4; 10:18; 24:14 e outros; <span class=\"greek\">εἰς ἄφεσιν ἁμαρτιῶν</span>, «para remissão dos pecados, de modo que os pecados sejam perdoados», Mt 26:28; cf. Mc 1:4; Lc 3:3; At 2:38; <span class=\"greek\">εἰς μνημόσυνόν τινος</span>, «em memória de alguém», Mt 26:13; Mc 14:9; cf. Lc 22:19 e outros (<span class=\"greek\">εἰς μνημόσυνον</span>, En 99:3).</p>\n<p><span class=\"greek\">εἰς ὅ</span>, «para cujo propósito» (Heródoto 2, 103, 1), Cl 1:29; diferentemente em 2Ts 1:11, «com isso em vista»; <span class=\"greek\">εἰς τί</span>;, «por quê?» (Sb 4:17; Sir 39:16, 21), Mt 14:31; Mc 14:4; 15:34; Hm 2:5; D 1:5. <span class=\"greek\">εἰς τοῦτο</span>, «por esta razão ou finalidade», Mc 1:38; Lc 4:43, variante; Jo 18:37; At 9:21; 26:16; Rm 9:17; 14:9; 2Co 2:9; 1Jo 3:8; Hs 1:9 (Justino, A I, 13, 3); <span class=\"greek\">εἰς αὐτὸ τοῦτο</span>, «precisamente para isto», 2Co 5:5; Ef 6:22; Cl 4:8. Seguido de infinitivo substantivado (Xenofonte, Ages. 9, 3; Mem. 3, 6, 2; Justino, A I, 9, 5), «a fim de» (frequentemente na LXX; com negação <span class=\"greek\">μή</span>, «a fim de não»; veja B-D-F §402, 2), Mt 20:19; 26:2; 27:31; Mc 14:55 e frequentemente. <span class=\"greek\">εἰς ὁδόν</span>, «para a viagem», Mc 6:8.</p>\n<p><strong>ⓖ Como no grego moderno, substitui o dativo</strong>, particularmente o dativo de vantagem, mas também significa «para» em geral (Xenofonte, An. 3, 3, 19: <span class=\"greek\">τ</span>. <span class=\"greek\">ἵππους εἰς ἱππέας κατασκευάσωμεν</span>, «preparemos os cavalos para os cavaleiros»; Licurgo 85: <span class=\"greek\">διεκαρτέρουν εἰς τ</span>. <span class=\"greek\">πατρίδα</span>, «perseveravam pela pátria»; UPZ 180a I, 7 [113 a.C.]: <span class=\"greek\">τὸν εἰς Τάγην οἶκον ᾠκοδομημένον</span>, «a casa construída para Tágis»; BGU 37, 4s. [51 d.C.]: <span class=\"greek\">ξύλα εἰς τοὺς ἐλαιῶνάς μου</span>, «madeira para meus olivais»; PLond I, 43, 9, p. 48 [século II a.C.]; PTebt 5, 77; POxy 37 I, 9; EpJer 9; Sir 37:7s.; Jd 14:2; Bel 3, Teodócio; versículo 22, LXX). <span class=\"greek\">εἰς πάντα τ</span>. <span class=\"greek\">λαόν</span>, «para todo o povo», Lc 9:13; cf. 3Jo 5; <span class=\"greek\">εἰς ἡμᾶς</span>, «para nós», Ef 1:19; cf. Cl 1:25; 1Ts 4:10; Rm 10:12; <span class=\"greek\">χρείαν ἔχειν εἰς τ</span>. <span class=\"greek\">ἑορτήν</span>, «ter necessidade para a festa», Jo 13:29; cf. Mc 8:19s.; Gl 2:8; 1Ts 2:9; 5:15 e outros.</p>\n<p><span class=\"greek\">εἰς</span> é comumente empregado para indicar a pessoa em favor da qual é efetuado pagamento etc. (Deissmann, B 113–115; NB 23 [BS 117s.; 194s.]), 1Co 16:1; 2Co 8:4; 9:1, 13; Rm 15:26; At 24:17. <span class=\"greek\">εἰς λόγον τινός</span>, «em conta de alguém ou algo» (POxy 275, 19, 21 [66 d.C.]; 496, 10; 530, 15), Fp 4:15; cf. versículo 17. <span class=\"greek\">εἰς Χριστόν</span>, Fm 6, provavelmente «em honra de Cristo» (Tetrast. Iamb. 1, 7, 4, p. 266: <span class=\"greek\">εἰς θεούς</span>, «em honra dos deuses»; Platão, Lysis 205d: <span class=\"greek\">ᾂδεις εἰς σαυτὸν ἐγκώμιον</span>, «cantas um elogio a ti mesmo»; Pseudo-Platão, Minos 319c; Ateneu 15, 667c; Sinésio, Ep. 75, p. 222b).</p>\n<p><strong>⑤ Indicador de ponto específico de referência; para, a, quanto a, com respeito a, com referência a.</strong> (Arriano, Anab. 6, 26, 3: <span class=\"greek\">τοῦτο τὸ ἔργον εἰς καρτερίαν ἐπαινῶ Ἀλεξάνδρου</span>, «louvo essa ação em vista da perseverança de Alexandre»; Ath. 31, 1: <span class=\"greek\">οὐδὲν χείρους εἰς ἀρετῆς λόγον</span>, «em nada inferiores no tocante à excelência»). <span class=\"greek\">εὔθετος εἴς τι</span>, «adequado para alguma coisa», Lc 14:35; igualmente <span class=\"greek\">εὔχρηστος</span>, «útil», 2Tm 4:11; <span class=\"greek\">ἡτοιμασμένος</span>, «preparado para», 2Tm 2:21; <span class=\"greek\">εὐκαιρέω εἴς τι</span>, «ter oportunidade para», At 17:21; <span class=\"greek\">ἱκανόω</span>, «capacitar para», Cl 1:12; <span class=\"greek\">ἰσχύω</span>, «ter força para», Mt 5:13; <span class=\"greek\">περισσεύω</span>, «abundar para», 2Co 9:8; <span class=\"greek\">συνεργέω</span>, «cooperar para», Rm 8:28. <span class=\"greek\">τοῦτο οὐκ εἰς ταύτας τ</span>. <span class=\"greek\">ἡμέρας λέγω</span>, «não digo isto com referência a estes dias», Hs 9, 26, 6. Depois dos verbos <span class=\"greek\">ἀπορέομαι</span>, <span class=\"greek\">διακρίνομαι</span>, <span class=\"greek\">καυχάομαι</span>, <span class=\"greek\">παρρησίαν ἔχω</span>, veja os respectivos verbetes; depois dos adjetivos <span class=\"greek\">ἄκαρπος</span>, <span class=\"greek\">ἀκέραιος</span>, <span class=\"greek\">βραδύς</span>, <span class=\"greek\">σοφός</span>, <span class=\"greek\">συνεργός</span>, <span class=\"greek\">ὑπήκοος</span>, <span class=\"greek\">φρόνιμος</span>, idem.</p>\n<p>Com acusativo de pessoa: <span class=\"greek\">ἀσθενεῖν εἴς τινα</span>, «ser fraco para com alguém», 2Co 13:3; <span class=\"greek\">εὐδοκεῖν</span>, «agradar-se de», 2Pe 1:17; <span class=\"greek\">λέγειν εἴς τινα</span>, «dizer com referência a alguém» (Diodoro Sículo 11, 50, 4; Justino, D. 77, 1: <span class=\"greek\">εἰς Χριστὸν</span> … <span class=\"greek\">εἰρῆσθαι</span>, «ter sido dito acerca de Cristo»), At 2:25. Sobre Rm 6:17, veja o fim de <span class=\"greek\">παραδίδωμι</span> ①ⓑ. <span class=\"greek\">δέχομαί τινα εἰς ὄνομά τινος</span>, «receber alguém em nome de outrem», Mt 10:41s.; veja <span class=\"greek\">ὄνομα</span> ①ⓓ<span class=\"greek\">γ</span><bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">א</bdi>.</p>\n<p><strong>⑥ Indicador de garantia; por.</strong> <span class=\"greek\">ὀμνύναι εἴς τι</span>, «jurar por alguma coisa», Mt 5:35 (cf. PGiss 66, 8s. [início do século II d.C.]: <span class=\"greek\">ἐρωτῶ εἰς τὴν τ</span>. <span class=\"greek\">θεῶν εὐσέβειαν</span>, «rogo pela reverência aos deuses»; mas o emprego isolado de <span class=\"greek\">εἰς</span> numa série de dativos com <span class=\"greek\">ἐν</span> pode refletir bilinguismo; sobre possível perspectiva hebraica, veja M’Neile, comentário ad loc.).</p>\n<p><strong>⑦ Indicador distributivo.</strong> Com números, <span class=\"greek\">εἰς</span> funciona distributivamente no sentido de «-vezes» (cf. <span class=\"greek\">ἐστρίς</span>, «até três vezes», Píndaro, O. 2, 68; GDI IV, p. 884, n.º 62, 36 [século IV a.C.]), Mc 4:8, variante de leitura. Diferentemente, <span class=\"greek\">ἐς τετρακοσίους</span> e <span class=\"greek\">ἐς ὀγδοήκοντα</span> significam «cerca de quatrocentos», «cerca de oitenta» (Arriano, Anab. 5, 15, 2; 6, 2, 4; 7, 20, 3).</p>\n<p><strong>⑧ Sob influência semítica, que fortaleceu tendências gregas semelhantes, o nominativo e o acusativo predicativos são por vezes substituídos por <span class=\"greek\">εἰς</span> com acusativo.</strong></p>\n<p><strong>ⓐ Nominativo predicativo. <span class=\"greek\">α</span>. Com <span class=\"greek\">γίνεσθαι</span>:</strong> (PFay 119, 34 [100 d.C.]: <span class=\"greek\">ἵνα μὴ εἰς ψωμίον γένηται</span>, «para que não se transforme em um pequeno pedaço de pão»; Sb 14:11; 1Mac 1:36; 10:70; Jd 5:10, 18 e outros), Mt 21:42 (Sl 117:22); <span class=\"greek\">ἐγένετο εἰς δένδρον</span>, «tornou-se árvore», Lc 13:19; cf. Jo 16:20; At 5:36; Ap 8:11; 16:19.</p>\n<p><strong><span class=\"greek\">β</span>. Com <span class=\"greek\">εἶναι</span>:</strong> (Br 2:23; Jd 5:21, 24; Sir 31:10 e outros), Mt 19:5 (Gn 2:24); Lc 3:5 (Is 40:4); 2Co 6:18; Hb 1:5; 8:10 (nessas três últimas passagens são também reproduzidas expressões do Antigo Testamento). Não derivado do Antigo Testamento: 1Jo 5:8.</p>\n<p><strong><span class=\"greek\">γ</span>. Com <span class=\"greek\">λογίζεσθαι εἰς</span>:</strong> (Sb 2:16; 1Mac 2:52), Rm 4:3 (Gn 15:6); cf. 2:26; 9:8. <span class=\"greek\">λογίζεσθαι εἰς οὐθέν</span>, «considerar como nada» (Is 40:17; Sb 3:17; cf. 9:6), At 19:27.</p>\n<p><strong>ⓑ Acusativo predicativo:</strong> (Heliodoro 6, 14, 1: <span class=\"greek\">τ</span>. <span class=\"greek\">πήραν εἰς καθέδραν ποιησαμένη</span>, «utilizando a bolsa como assento»; Vettius Valens 59, 7; 1Mac 10:54; 11:62; Jd 5:11 e outros; JosAs 13:12: <span class=\"greek\">παράθου με αὐτῷ εἰς παιδίσκην</span>, «apresenta-me a ele como serva»). <span class=\"greek\">ἐγείρειν τινὰ εἰς βασιλέα</span>, «levantar alguém como rei», At 13:22 (cf. 1Rs 13:14); <span class=\"greek\">ἀνατρέφεσθαί τινα εἰς υἱόν</span>, «criar alguém como filho», At 7:21 (cf. Êx 2:10); <span class=\"greek\">τέθεικά σε εἰς φῶς ἐθνῶν</span>, «estabeleci-te como luz das nações», At 13:47 (cf. Is 49:6); cf. Mt 21:46; 1Cl 42:4. — B-D-F §§145; 157, 5; Rdm.² 20s.; Mlt. 71s.; Mlt-H. 462; Johannessohn, Kasus 4s.</p>\n<p><strong>⑨ Indicador de instrumentalidade; mediante, por, com.</strong> (Arriano, Anab. 5, 12, 3: <span class=\"greek\">ἐς ἀκρίβειαν</span>, «com exatidão»; Vi. Aesopi I G 7 P.: <span class=\"greek\">νικᾶν εἰς εὐσέβειαν πάντα ψόγον</span>, «vencer toda censura pela piedade».) <span class=\"greek\">εἰς διαταγὰς ἀγγέλων</span>, «por determinações de anjos», At 7:53 (= <span class=\"greek\">ἐν διαταγαῖς</span>; B-D-F §206, 1). Semelhantemente <span class=\"greek\">ὕπαγε εἰς εἰρήνην</span>, «vai em paz» (1Rs 1:17), Mc 5:34; Lc 7:50; 8:48 (= <span class=\"greek\">ἐν εἰρήνῃ</span>). Mlt-Turner 254s.</p>\n<p><strong>⑩ Outros empregos de <span class=\"greek\">εἰς</span>.</strong></p>\n<p><strong>ⓐ Em resposta a, diante de.</strong> <span class=\"greek\">μετανοεῖν εἰς τὸ κήρυγμα</span>, «arrepender-se diante da proclamação», Mt 12:41; Lc 11:32; cf. Rm 4:20 e talvez Mt 3:11. J. Mantey, JBL 70, 1951, 45–48 e 309–311, defende aqui uso causal, «por causa da proclamação», com referências; contra essa interpretação, R. Marcus, ibid. 129s.; JBL 71, 1952, 43s.; J. Davis, Restoration Quarterly 24, 1981, 80–88.</p>\n<p><strong>ⓑ Para <span class=\"greek\">βαπτίζω εἰς</span></strong>, veja <span class=\"greek\">βαπτίζω</span> ②ⓒ.</p>\n<p><strong>ⓒ <span class=\"greek\">μένειν εἰς</span>, «permanecer com»</strong> (PFay 111, 12 [95/96 d.C.]); talvez assim em Jo 6:27.</p>\n<p><strong>ⓓ Em construções condensadas, nas quais se subentende deslocamento ou resultado.</strong> <span class=\"greek\">σῴζειν εἰς</span>, «levar em segurança para», 2Tm 4:18 (cf. Xenofonte, An. 6, 4, 8; Diodoro Sículo 2, 48; Cebes 27; SIG 521, 26 [século III a.C.]; OGI 56, 11; 4Mac 15:3). <span class=\"greek\">διασῴζειν</span>, «salvar e fazer chegar», 1Pe 3:20 (cf. Gn 19:19); <span class=\"greek\">μισθοῦσθαι ἐργάτας εἰς τ</span>. <span class=\"greek\">ἀμπελῶνα</span>, «contratar trabalhadores para irem à vinha», Mt 20:1; <span class=\"greek\">ἐλευθεροῦσθαι εἰς</span>, «ser liberto para ingressar em», Rm 8:21; <span class=\"greek\">ἀποδιδόναι τινὰ εἰς Αἴγυπτον</span>, «entregar alguém [como escravo] ao Egito», At 7:9 (cf. Gn 37:28). <span class=\"greek\">ἔνοχος εἰς τ</span>. <span class=\"greek\">γέενναν</span>, «sujeito à geena», Mt 5:22; cf. Mt 10:9; Mc 6:8; Jo 20:7. — DELG. M-M. TW.</p></div></section></article> <article id=\"entry-heis-numeral-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἷς, μία, ἕν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heîs, mía, hén⟧</span><span class=\"separator\">·</span><span>numeral cardinal e adjetivo pronominal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Genitivo <span class=\"greek\">ἑνός</span>, <span class=\"greek\">μιᾶς</span>, <span class=\"greek\">ἑνός</span>. Termo numeral: <strong>um, uma</strong> (Homero e seguintes).</p>\n<p><strong>① Uma só pessoa ou coisa, com ênfase no aspecto quantitativo; um, uma.</strong></p>\n<p><strong>ⓐ Em contraste com mais de uma. <span class=\"greek\">α</span>. Como adjetivo:</strong> <span class=\"greek\">μίλιον ἕν</span>, «uma milha», Mt 5:41; cf. 20:12; 25:15, 24; At 21:7; 28:13; 2Pe 3:8. Em oposição a <span class=\"greek\">πάντες</span>, «todos», Rm 5:12 (<span class=\"greek\">εἷς ἄνθρωπος</span>, «um só homem», como Hipócrates, Ep. 11, 2 [IX, p. 326]; S. Hanson, Unity of the Church in the NT, 1946, 65–73, com bibliografia). Em oposição à nação, Jo 11:50; 18:14 (cf. Enômao em Eusébio, PE 5, 25, 5: <span class=\"greek\">μεῖον εἶναι ἕνα ἀντι πάντων πεσεῖν τὸν βασιλέα</span>, «seria mal menor cair um em lugar de todos, a saber, o rei»).</p>\n<p><strong><span class=\"greek\">β</span>. Como substantivo:</strong> Lc 23:16 [17], variante; com genitivo partitivo (Diodoro Sículo 1, 91, 5: <span class=\"greek\">αὐτῶν εἷς</span>, «um deles»; Josefo, Vi. 204; Justino, A I, 1, 1 e outros), Mt 5:19; 6:29; 18:6; Mc 9:42; Lc 12:27; 15:21, variante; 17:2, 22; 23:39; Jo 19:34. Ou com <span class=\"greek\">ἐκ</span> (Máximo de Tiro 1, 6ab: <span class=\"greek\">ἐκ πολλῶν εἷς</span>, «um dentre muitos»; Luciano, Somn. 9; Josefo, Bell. 7, 47), Mt 18:12; 22:35; 26:21; Mc 14:18; Jo 1:40; 6:8; At 11:28 e outros. <span class=\"greek\">ὁ εἷς τῶν δώδεκα</span>, «um dos Doze», Mc 14:10, é expressão peculiar (cf. BGU 1145, 25 [18 a.C.]: <span class=\"greek\">ὁ εἷς αὐτῶν Ταυρῖνος</span>, «um deles, Taurino»; UPZ 161, 50; 54; PTebt 138; 357, 10).</p>\n<p><strong>ⓑ Em contraste com as partes que compõem um todo.</strong> (Teofrasto em Apolônio Paradoxógrafo 16: <span class=\"greek\">τὰ πολλὰ ἓν γίγνεσθαι</span>, «muitos se tornarem um»; Estêvão de Bizâncio, s.v. <span class=\"greek\">Ὠκεανός</span>: <span class=\"greek\">γίγνεται ἐκ δύο εἰς ἕν</span>, «de dois torna-se um»; Justino, D. 103, 5: <span class=\"greek\">ἐξ ἀμφοτέρων</span> … <span class=\"greek\">ἓν ὄνομα</span>, «de ambos… um único nome».) <span class=\"greek\">ἔσονται οἱ δύο εἰς σάρκα μίαν</span>, «os dois serão uma só carne», Mt 19:5; Mc 10:8; 1Co 6:16 (as três citações de Gn 2:24). <span class=\"greek\">οἱ πολλοὶ ἓν σῶμά ἐσμεν</span>, «nós, embora muitos, formamos um só corpo», Rm 12:5; cf. 1Co 12:12, 20; Ef 2:15. <span class=\"greek\">πάντες εἷς ἐστε</span>, «todos vós sois um», Gl 3:28; <span class=\"greek\">ἕν εἰσιν</span>, «são um», 1Co 3:8; cf. Jo 10:30; 17:11, 21–23 (cf. 1QS 5, 2; Justino, D. 42, 3: <span class=\"greek\">ἓν ὄντες πρᾶγμα</span>, «sendo uma só realidade»). Também <span class=\"greek\">εἰς τὸ ἕν</span>, «para o mesmo», 1Jo 5:8 (Apiano, Iber. 66 §280: <span class=\"greek\">ἐς ἕν</span>, «juntos, como unidade»); <span class=\"greek\">εἰς ἕν</span>, «em um só», Jo 11:52 (cf. 1QS 5, 7); <span class=\"greek\">ὁ ποιήσας τὰ ἀμφότερα ἕν</span>, «aquele que uniu ambas as partes», Ef 2:14. — M. Appold, The Oneness Motif (John), 1976.</p>\n<p><strong>ⓒ Seguido de negação:</strong> <span class=\"greek\">εἷς</span> … <span class=\"greek\">οὐ</span> (<span class=\"greek\">μή</span>), «nem um sequer», mais enfático que <span class=\"greek\">οὐδείς</span> (Aristófanes, Eccl. 153; Thesm. 549; Xenofonte, An. 5, 6, 12; Demóstenes 30, 33: <span class=\"greek\">ἡ γυνὴ μίαν ἡμέραν οὐκ ἐχήρευσεν</span>, «a mulher não permaneceu viúva sequer um dia»; Dionísio de Halicarnasso, Comp. Verb. 18). <span class=\"greek\">ἓν ἐξ αὐτῶν οὐ πεσεῖται</span>, «nem um deles cairá», Mt 10:29 (Luciano, Herm. 28: <span class=\"greek\">ἓν ἐξ ἁπάντων</span>, «um dentre todos»); cf. Mt 5:18; Mc 8:14; Lc 11:46; 12:6. Raramente a negação vem primeiro, Mt 5:36.</p>\n<p><strong>② Entidade única, com ênfase na uniformidade ou qualidade; um só.</strong></p>\n<p><strong>ⓐ Um e o mesmo</strong> (Píndaro, N. 6, 1: <span class=\"greek\">ἓν ἀνδρῶν</span>, <span class=\"greek\">ἓν θεῶν γένος</span>· <span class=\"greek\">ἐκ μιᾶς δὲ πνέομεν ἀμφότεροι</span>, «uma é a raça dos homens, uma a dos deuses; ambos respiramos de uma só origem»; Díon Crisóstomo 19 [36], 6; Máximo de Tiro 19, 4a; cf. OGI 383, 59 [século I a.C.: a estátua do governante deve ser feita da espécie de pedra usada nas estátuas dos deuses]; Gn 11:1; 40:5; Lv 22:28; Sb 7:6; Ar. 13, 5: <span class=\"greek\">μία φύσις τῶν θεῶν</span>, «uma só natureza dos deuses»). <span class=\"greek\">ἐν ἑνὶ οἴκῳ</span>, «na mesma casa», Lc 12:52 (Diodoro Sículo 14, 43, 1: <span class=\"greek\">ἐν ἑνὶ τόπω</span>, «no mesmo lugar»).</p>\n<p>Expressando unanimidade: <span class=\"greek\">ἐν ἑνὶ στόματι</span>, «a uma só voz», Rm 15:6; <span class=\"greek\">τοῦ ἑνὸς ἄρτου</span>, «do mesmo pão», 1Co 10:17; <span class=\"greek\">εἷς ὁ θεός</span>, «um e o mesmo Deus» (Anfíteo de Heracleia, fragmento 431 Fgm. 1b Jac.: <span class=\"greek\">Διόνυσος κ</span>. <span class=\"greek\">Σαβάζιος εἷς ἐστι θεός</span>, «Dioniso e Sabázio são um só deus»; diferentemente, Ath. 10, 2: <span class=\"greek\">ἑνὸς ὄντος τοῦ πατρὸς καὶ τοῦ υἱοῦ</span>, «sendo um o Pai e o Filho»), Rm 3:30; cf. 9:10; 1Co 6:16s.; 12:9, 13.</p>\n<p><span class=\"greek\">εἷς κύριος</span>, <span class=\"greek\">μία πίστις</span>, <span class=\"greek\">ἓν βάπτισμα</span>· <span class=\"greek\">εἷς θεός κτλ</span>., «um Senhor, uma fé, um batismo, um Deus etc.» (cf. o emprego consecutivo dos três gêneros de <span class=\"greek\">εἷς</span> em Simônides 97 Diehl²: <span class=\"greek\">ἓν πέλαγος</span>, <span class=\"greek\">μία ναῦς</span>, <span class=\"greek\">εἷς τάφος</span>, «um mar, um navio, um túmulo» [dos náufragos]; Justino, D. 63, 5: <span class=\"greek\">μιᾷ ψυχῇ</span> … <span class=\"greek\">συναγωγῇ</span> … <span class=\"greek\">ἐκκλησίᾳ</span>, «uma só alma… assembleia… igreja»), Ef 4:5s. (NJklA 35, 1915, 224ss. A repetição de <span class=\"greek\">εἷς</span> é como em Herm. Wr. 11, 11; Epicteto 3, 24, 10ss.). — Ap 9:13; 18:8; At 17:26.</p>\n<p><span class=\"greek\">ἐν ἑνὶ πνεύματι</span>, <span class=\"greek\">μιᾷ ψυχῇ</span>, «em um só espírito, uma só alma», Fp 1:27; cf. At 4:32 (Aristóteles, EN 9, 8, 2; Plutarco, Mor. 478c). <span class=\"greek\">τὸ ἓν φρονεῖν</span>, «ter um só pensamento», Fp 2:2. <span class=\"greek\">συνάγειν εἰς ἕν</span>, «reunir, congregar em unidade» (Platão, Phileb. 23e; Dionísio de Halicarnasso 2, 45, 3: <span class=\"greek\">συνάξειν εἰς ἓν τὰ ἔθνη</span>, «unir os povos»; POxy 1411, 3: <span class=\"greek\">τῶν δημοσίων εἰς ἓν συναχθέντων</span>, «reunidas as receitas públicas»; TestJob 28:5: <span class=\"greek\">τὰ χρήματα ἐὰν συναχθῇ εἰς ἓν ἐπὶ τὸ αὐτό</span>, «se todos os nossos bens fossem reunidos no mesmo lugar»; Josefo, Bell. 3, 518), Jo 11:52.</p>\n<p><span class=\"greek\">τὸ ἓν καὶ τὸ αὐτό</span>, «um e o mesmo», 1Co 12:11 (cf. Diodoro Sículo 11, 47, 3; 17, 104, 6; Epicteto 1, 11, 28; 1, 19, 15; Justino, D. 123, 1: <span class=\"greek\">ἑνὸς καὶ τοῦ αὐτοῦ</span> … <span class=\"greek\">νόμου</span>, «de uma e mesma lei»); cf. <span class=\"greek\">ἓν καὶ αὐτό τινι</span>, «a mesma coisa para alguém», 1Co 11:5. <span class=\"greek\">εἰς ἕνα τόπον</span>, «num lugar à parte», Jo 20:7 (Josefo, Ant. 6, 125).</p>\n<p><strong>ⓑ [Um] único, somente um.</strong> (Diodoro Sículo 16, 11, 2; Apiano, Bell. Civ. 2, 44 §180: <span class=\"greek\">εἷς ἀνήρ</span>, «um só homem»; Máximo de Tiro 11, 6c: <span class=\"greek\">μαντεῖον ἕν</span>, «um só oráculo»; Justino, D. 141, 3: <span class=\"greek\">τῆν μίαν τοῦ Δαυεὶδ</span> … <span class=\"greek\">παράπτωσιν</span>, «a única falta de Davi».) <span class=\"greek\">λόγον ἕνα</span>, «uma só palavra», Mt 21:24 (GrBar 5:1); Gl 5:14; <span class=\"greek\">ἕνα ἄρτον</span>, «um pão», Mc 8:14; <span class=\"greek\">εἷς ἄρτος</span>, «um só pão», 1Co 10:17a (<span class=\"greek\">εἷς ἄρτος</span> também simboliza a unidade da comunidade pitagórica, Diógenes Laércio 8, 35, que acrescenta que <span class=\"greek\">οἱ βάρβαροι</span>, «os bárbaros», também sustentam a mesma ideia <span class=\"greek\">ἔτι καὶ νῦν</span>, «até hoje»); <span class=\"greek\">πῆχυν ἕνα</span>, «um côvado», Mt 6:27 (veja <span class=\"greek\">πῆχυς</span>); <span class=\"greek\">ἓν μέλος</span>, «um membro», 1Co 12:26; <span class=\"greek\">ἓν ἔργον</span>, «uma obra», Jo 7:21 (aqui <span class=\"greek\">καί</span>, depois de <span class=\"greek\">ἕν</span>, acrescenta indicação da grandeza do feito, como em Apiano, Bell. Civ. 2, 133 §555: <span class=\"greek\">ἓν ἐκ τῶν Καίσαρος ἔργων προὔθηκα</span> …, <span class=\"greek\">καί</span>, «apresentei uma das obras de César… e…»); <span class=\"greek\">εἷς ἐστιν ὁ ἀγαθός</span>, «um só é o bom», Mt 19:17; <span class=\"greek\">ποιῆσαι ἕνα προσήλυτον</span>, «fazer um único prosélito», Mt 23:15; <span class=\"greek\">ἕνα εἶχεν υἱὸν ἀγαπητόν</span>, «tinha um único filho, a quem amava muito», Mc 12:6 (<span class=\"greek\">εἷς υἱός</span> como em Fálaris, Ep. 18).</p>\n<p><span class=\"greek\">ὁ δὲ θεὸς εἷς ἐστιν</span>, «mas Deus é um só», Gl 3:20; cf. Mc 12:32; 1Co 8:4, 6 (variante de leitura acrescenta a «Deus Pai» e a «Jesus Cristo»: <span class=\"greek\">ἓν πνεῦμα ἅγιον κτλ</span>., «um Espírito Santo etc.»; cf. Máximo de Tiro 11, 5a: <span class=\"greek\">θεὸς εἷς</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">πατήρ</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">θεοὶ πολλοί</span>, «um só deus… e pai, embora muitos deuses»; já Xenófanes, fragmento 19 Diehl³: <span class=\"greek\">εἷς θεὸς ἔν τε θεοῖσι κ</span>. <span class=\"greek\">ἀνθρωποῖσι μέγιστος</span>, «um deus, o maior entre deuses e homens» [= fragmento 23 Diels]); Tg 2:19; PtK 3, p. 15, 20 (Herm. Wr. 11, 11; 14: <span class=\"greek\">εἷς ὁ θεός</span>, «um só é Deus»; POxy 1382, 20: <span class=\"greek\">εἷς Ζεὺς Σάραπις</span>, «um só é Zeus Serápis»; Sb 159, 1: <span class=\"greek\">εἷς θεὸς ὁ βοηθῶν ὑμῶν</span>, «um só deus é o vosso auxiliador»; Fílon, Spec. Leg. 1, 67; Josefo, Ant. 5, 97: <span class=\"greek\">θεός τε εἷς</span>, «Deus é um só»; 8, 343; C. Ap. 2, 193; SibOr 4, 30 e fragmento 1, 7; Ath. 6, 1: <span class=\"greek\">μονάς ἐστιν ὁ θεός</span>, <span class=\"greek\">τοῦτ</span>’ <span class=\"greek\">ἔστιν εἷς</span>, «Deus é unidade, isto é, um»; 6, 4: <span class=\"greek\">ὁ θεὸς εἷς</span>, «Deus é um»; veja E. Peterson, <span class=\"greek\">Εἷς Θεός</span>, 1926; Der Monotheismus als politisches Problem, 1935; referências adicionais em Horst, Ps.-Phoc., pp. 151s.). <span class=\"greek\">εἷς ἐστιν ὑμῶν ὁ διδάσκαλος</span>, «um só é o vosso Mestre», Mt 23:8; cf. versículo 9.</p>\n<p><span class=\"greek\">μιᾶς γυναικὸς ἀνήρ</span>, «marido casado uma só vez» (numerosas inscrições funerárias louvam a virtude do cônjuge sobrevivente observando que ele ou ela foi casado apenas uma vez, sugerindo assim fidelidade extraordinária, por exemplo CIL VI, 3604; 723; 12405; 14404; cf. Horácio, Odes 3, 14, 4; Propércio 4, 11, 36; Valério Máximo 4, 3, 3; veja sobretudo CIL VI, 1527, 31670, 37053 = ILS 8393 [texto e tradução inglesa em E. Wistrand, The So-Called Laudatio Turiae, 1976]; G. Williams, JRS 48, 1958, 16–29. Quanto a <span class=\"greek\">μία</span> aplicada a uma mulher: Élio Aristides 46, p. 346 D.: <span class=\"greek\">ὑπὲρ μιᾶς γυναικός</span>, «por uma única mulher»; <span class=\"greek\">μία γυνή</span> é bastante frequente: Diodoro Sículo 17, 72, 6; cf. 1, 80, 3, em que <span class=\"greek\">γαμοῦσι μίαν</span> significa simplesmente que os sacerdotes casavam somente uma vez, não que levassem vida rigorosamente moral, conceito para o qual os gregos jamais empregam a expressão <span class=\"greek\">μιᾶς γυναικὸς ἀνήρ</span> ou outra semelhante; Hipóstrato [século III a.C.], fragmento 568 Fgm. 1 Jac.; Apiano, Bell. Civ. 4, 95 §402; Ath. 33, 2: <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑνὶ γάμῳ</span>, «num único casamento»; Ath. qualifica segundo casamento como <span class=\"greek\">εὐπρεπής μοιχεία</span>, «adultério disfarçado»), 1Tm 3:2, 12; Tt 1:6. Outros traduzem «marido de uma só esposa» (por exemplo, RSV em impressões posteriores; REB).</p>\n<p>Correspondentemente, <span class=\"greek\">ἑνὸς ἀνδρὸς γυνή</span>, «mulher casada uma só vez» (cf. a conduta exemplar de Ana, Lc 2:36; Pausânias 7, 25, 13: a sacerdotisa da deusa Terra deve ter sido, antes de se tornar sacerdotisa, uma mulher que não tenha tido <span class=\"greek\">πλέον ἢ ἑνὸς ἀνδρὸς ἐς πεῖραν ἀφιγμένη</span>, «experiência com mais de um homem»), 1Tm 5:9.</p>\n<p>Absolutamente, 1Co 9:24; 2Co 5:14. <span class=\"greek\">μεσίτης ἑνός</span>, «intermediário de uma só parte», Gl 3:20; cf. Tg 4:12. <span class=\"greek\">οὐδὲ εἷς</span>, «nem sequer um» (Xenofonte, Mem. 1, 6, 2; Cyr. 1, 3, 10 e outros; Sir 42:20; 49:14, variante; 1Mac 11:70), Mt 27:14; At 4:32. Frequentemente no fim de sentença ou oração (referências da comédia em E. Schwartz, NGG 1908, p. 534, nota 3; também Hermocles [séculos IV–III a.C.], p. 174, 17 Coll. Alex.; Díon Crisóstomo 21 [38], 23; Élio Aristides 28, 156 K. = 49, p. 542 D.; 53, p. 617 D.; Epicteto 2, 18, 26; Enchir. 1, 3; Filônides em Estobeu 3, 35, 6, ed. Hense III, p. 688; Mitt-Wilck. I/2, 59, 5 [39 d.C.]; Bel 18, Teodócio; 1Mac 7:46), Rm 3:10; <span class=\"greek\">οὐδὲ ἕν</span> seguido de <span class=\"greek\">ἐὰν μή</span>, Jo 3:27.</p>\n<p>Isso constitui bom motivo para colocar o ponto depois de <span class=\"greek\">οὐδὲ ἕν</span> em Jo 1:3 (veja G. Bergh van Eysinga, PM 13, 1909, 143–150; E. Hennecke, Congrès d’Histoire du Christianisme I, 1928, 207–219; M. d’Asbeck, ibid. 220–228; R. Eisler, Revue de Philologie, terceira série 4, 1930, 350–371; B. Vawter, CBQ 25, 1963, 401–406; K. Aland, ZNW 59, 1968, 174–209; Metzger 195s.; <span class=\"greek\">γίνομαι</span> ②ⓐ), mas a ausência de pontuação interna nos manuscritos mais antigos legitima considerar outras pontuações.</p>\n<p><span class=\"greek\">οὐκ ἔστιν ἕως ἑνός</span>, «não há nem sequer um», Rm 3:12 (Sl 13:3; Justino, D. 103, 2: <span class=\"greek\">οὐδὲ μέχρις ἑνὸς ἀνθρώπου</span>, «nem um único homem»). <span class=\"greek\">μία εἴσοδος</span>, «a única entrada», Hs 9, 12, 6. <span class=\"greek\">ἕν</span>, «uma única coisa»: <span class=\"greek\">ἔτι ἕν σοι λείπει</span>, «ainda te falta uma única coisa» (Josefo, Bell. 4, 257), Lc 18:22; <span class=\"greek\">ἕν σε ὑστερεῖ</span>, «falta-te uma só coisa», Mc 10:21; cf. Lc 10:42; <span class=\"greek\">ἓν οἶδα</span>, «ao menos uma coisa sei», Jo 9:25; <span class=\"greek\">ἓν δὲ τοῦτο</span>, «esta única coisa» (Porfírio, Vi. Plot. 19; Justino, D. 115, 6: <span class=\"greek\">ἓν δὲ μικρὸν ὁτιοῦν</span>, «uma pequena coisa qualquer»), 2Pe 3:8; <span class=\"greek\">ἓν δέ</span> é uma curta frase interjetiva (como em Xenofonte de Éfeso 1, 5, 3: <span class=\"greek\">τοσοῦτο δέ</span>, «somente isto!»): «uma coisa apenas!», Fp 3:13 (A. Fridrichsen, ConNeot 9, 1944, 31s.). — Em Gl 5:14, imagem comercial: <span class=\"greek\">εἷς λόγος</span>, «um único lançamento, uma rubrica» (cf. BGU 831, 13).</p>\n<p><strong>ⓒ Somente, exclusivamente.</strong> (<span class=\"greek\">οὐδεὶς</span>) … <span class=\"greek\">εἰ μὴ εἷς ὁ θεός</span>, «[ninguém]… senão Deus somente», Mc 2:7 (na passagem paralela, Lc 5:21: <span class=\"greek\">μόνος ὁ θεός</span>, «Deus somente»; cf. Herm. Wr. 11, 11: <span class=\"greek\">εἰ μὴ εἷς ὁ θεός</span> … <span class=\"greek\">εἰ μὴ μόνῳ τῷ θεῷ</span>); Mc 10:18; 12:29 (Dt 6:4); Mt 23:10; Lc 18:19. — E. Bishop, ET 49, 1938, 363–366.</p>\n<p><strong>③ Entidade não especificada; alguém, algum, um</strong>, equivalente a <span class=\"greek\">τις</span>; assim <span class=\"greek\">εἷς</span> pode ter exatamente a função de artigo indefinido (Aristófanes e outros [Av. 1292: <span class=\"greek\">εἷς κάπηλος</span>, «um comerciante»]; <span class=\"greek\">Περὶ ὕψους</span> 33, 4, p. 62, 18 V. [leitura do códice de Paris]: <span class=\"greek\">εἷς ἕτερος</span> com <span class=\"greek\">μή</span>, «por nenhuma outra razão»; Estrabão 5, 3, 2, 230c: <span class=\"greek\">ἐπηγγείλατο ἕνα ἀγῶνα ἱππικόν</span>, «anunciou uma competição equestre»; Sintipas, p. 29, 3: <span class=\"greek\">μία γαλῆ</span>, «uma doninha»; Apiano, Liby. 117 §554: <span class=\"greek\">νυκτὸς μιᾶς</span>, «numa noite»; Marco Diácono 27, 5: <span class=\"greek\">ἐν μιᾷ ἡμέρᾳ</span>, «em certo dia»; SIG 1170, 15 [160 d.C.]: <span class=\"greek\">μιᾷ ἡμέρᾳ</span>; UPZ 162 I, 27 [117 a.C.]; PAmh 30, 28 [século II a.C.]: <span class=\"greek\">Κονδύλου ἑνὸς τῶν ἁλιείων</span>, «Condilo, um dos pescadores»; BGU 1044, 6; Gn 21:15; Jd 14:6; 1Esdr 3:5; B-D-F §247, 2; Mlt. 96s.; Rob. 674s.; Mlt-Turner 195s.; E. Bruhn, RhM 49, 1894, 168–171; J. Wackernagel, Syntax II², 1928, 151; M. Black, An Aramaic Approach³, 1967, 104–106).</p>\n<p><strong>ⓐ Alguém, qualquer pessoa</strong>, Mt 18:24; 19:16; Mc 10:17; <span class=\"greek\">εἷς ὀνόματι Κλεοπᾶς</span>, «alguém chamado Cléopas», Lc 24:18. Frequentemente com genitivo partitivo seguinte (Aléxis 220, 5; Diodoro Sículo 20, 107, 5: <span class=\"greek\">εἷς τῶν φίλων</span>, «um dos amigos»; Epicteto 4, 2, 9; Díon Crisóstomo 71 [21], 15: <span class=\"greek\">εἷς τῶν Σπαρτῶν</span>, «um dos espartanos»; TestJob 26:6: <span class=\"greek\">μίαν τῶν</span> … <span class=\"greek\">γυναικῶν</span>, «uma das mulheres»; Josefo, Ant. 9, 106): <span class=\"greek\">ἕνα τῶν προφητῶν</span>, «um dos profetas», Mt 16:14 (termo depreciativo? Veja Reader, Polemo, p. 257); <span class=\"greek\">ἕνα τ</span>. <span class=\"greek\">συνδούλων</span>, «um dos conservos», Mt 18:28; <span class=\"greek\">ἐν μιᾷ τ</span>. <span class=\"greek\">πόλεων</span>, «em certa cidade», Lc 5:12; <span class=\"greek\">ἐν μιᾷ τ</span>. <span class=\"greek\">ἡμερῶν</span>, «num daqueles dias», versículo 17; cf. 15:19, 26; 22:47.</p>\n<p><strong>ⓑ Como artigo indefinido</strong> (veja início de ③): <span class=\"greek\">εἷς γραμματεύς</span>, «um escriba», Mt 8:19; <span class=\"greek\">συκῆν μίαν</span>, «uma figueira», Mt 21:19; cf. 26:69; Mc 12:42; <span class=\"greek\">παιδάριον ἕν</span>, «um menino», Jo 6:9, variante; <span class=\"greek\">ἑνὸς ἀετοῦ</span>, «uma águia», Ap 8:13; cf. 18:21; 19:17; <span class=\"greek\">ἄρχων εἷς ἐλθών</span>, «tendo vindo certo chefe», Mt 9:18; <span class=\"greek\">εἷς στέφανος</span>, «uma coroa», ApcPt 3:10; <span class=\"greek\">ἓν σῶμα</span>, «um corpo», AcPlCor 2:26.</p>\n<p><strong>ⓒ Empregado com <span class=\"greek\">τις</span></strong> (Platão, Tucídides e outros; Jd 2:13): <span class=\"greek\">εἷς τις νεανίσκος</span>, «certo jovem», Mc 14:51, variante. Com genitivo partitivo seguinte (Trífon de Alexandria [século I a.C.], em Ateneu 3, 78a: <span class=\"greek\">ἕνα τινὰ τ</span>. <span class=\"greek\">Τιτάνων</span>, «um dos Titãs»; Esopo, Fab. 300 H. = 30 P. e H-H.; Hiérocles 27, 484; IG XII/5, 445, 12 [século III a.C.]: <span class=\"greek\">ἕνα τινὰ αὐτῶν</span>, «um deles»; Élio Aristides 29, 14 K. = 40, p. 755 D.: <span class=\"greek\">εἷς τις τ</span>. <span class=\"greek\">χορευτῶν</span>, «um dos dançarinos»): <span class=\"greek\">εἷς τις τῶν παρεστηκότων</span>, «certo um dos presentes», Mc 14:47 (sobre a variante sem <span class=\"greek\">τις</span>, veja P. Dickerson, JBL 116, 1997, 302); também <span class=\"greek\">εἷς τις ἐξ αὐτῶν</span>, «certo um dentre eles» (Josefo, Vi. 290), Lc 22:50; Jo 11:49.</p>\n<p><strong>④ Indicador daquilo que vem primeiro; primeiro.</strong></p>\n<p><strong>ⓐ Talvez um hebraísmo:</strong> (cf. Nm 1:1: <span class=\"greek\">ἐν μιᾷ τοῦ μηνὸς τ</span>. <span class=\"greek\">δευτέρου</span>, «no primeiro [dia] do segundo mês»; 2Esdr 10:17; Est 1:1a; Josefo, Ant. 1, 29. Mas veja também Lido, Mens. 3, 4 W.: <span class=\"greek\">τὴν κεφαλὴν τ</span>. <span class=\"greek\">χρόνου οἱ Πυθαγόρειοι οὐχὶ πρώτην ἀλλὰ μίαν ὠνόμασαν</span>, «os pitagóricos chamavam o início do tempo não primeiro, mas um»; Calímaco, fragmento 550 P. [482 Schneider]: <span class=\"greek\">πρὸ μιῆς ὥρης</span>, «antes da primeira hora do dia».) Emprego em expressões temporais no lugar do ordinal: <span class=\"greek\">εἰς μίαν σαββάτων</span>, «no primeiro dia da semana», Mt 28:1; cf. Lc 24:1; Mc 16:2; Jo 20:1, 19; At 20:7; também <span class=\"greek\">κατὰ μίαν σαββάτου</span>, 1Co 16:2 (cf. Justino, D. 41, 4: <span class=\"greek\">τῇ μίᾳ τῶν σαββάτων ἡμέρᾳ</span>, «no primeiro dia da semana»; 27, 5 [aqui com <span class=\"greek\">πρό</span> e <span class=\"greek\">μετά</span>, respectivamente, segundo o uso latino]).</p>\n<p><strong>ⓑ Não semítico:</strong> (Heródoto 4, 161: <span class=\"greek\">μία</span>, <span class=\"greek\">ἄλλη</span>, <span class=\"greek\">τρίτη</span>, «uma, outra, terceira»; Élio Aristides 36, 40 K. = 48, p. 453 D.: <span class=\"greek\">ἕν</span>, <span class=\"greek\">δεύτερον</span>, <span class=\"greek\">τρίτον</span>, <span class=\"greek\">τέταρτον</span>, «um, segundo, terceiro, quarto»; JosAs 2:17). <span class=\"greek\">εἷς καὶ δεύτερος</span>, «primeiro e segundo», Tt 3:10 (cf. Alcífron, Ep. 1, 9, 2; Galeno XII 746 K.: <span class=\"greek\">ὕδωρ ὄμβριον ἔγχριε μέχρι μιᾶς καὶ δευτέρας ἡμέρας</span>, «aplica água da chuva até o primeiro e segundo dia»; Máximo de Tiro 28, 2h: <span class=\"greek\">μίαδευτέρα</span>; EpArist 143; Josefo, Ant. 11, 150; 16, 350: <span class=\"greek\">πεσόντος ἑνός καὶ δευτέρου</span>, «tendo caído o primeiro e o segundo»). Veja também <span class=\"greek\">ἡ οὐαὶ ἡ μία</span>, «o primeiro ai», Ap 9:12. — <span class=\"greek\">ἓν τριάκοντα</span>, Mc 4:8, 20, provavelmente um aramaísmo: «trinta vezes, trinta por um» (B-D-F §248, 3; E. Kautzsch, Grammatik des biblischen Aramäisch, 1884, §66, 2; J. Hudson, ET 53, 1941/1942, 266s.).</p>\n<p><strong>⑤ Combinações especiais.</strong></p>\n<p><strong>ⓐ <span class=\"greek\">εἷς</span> … <span class=\"greek\">εἷς</span>, «um… o outro».</strong> (Homero e outros: <span class=\"greek\">εἷς μὲν</span> … <span class=\"greek\">εἷς δέ</span>; Xenofonte, Cyr. 1, 2, 4; Aristóteles, Rhet. 2, 20, 1393a; papiros em Mitt-Wilck. I/2, 50, 11 e 13 [século III a.C.]: <span class=\"greek\">ἓν μὲν</span> … <span class=\"greek\">ἓν δέ</span>, «uma… outra»; II/2, 372 V, 14 [século II d.C.]: <span class=\"greek\">ὁ εἷς</span> … <span class=\"greek\">ὁ εἷς</span>; POxy 1153, 14 [século I d.C.]: <span class=\"greek\">ἓν μὲν</span> … <span class=\"greek\">καὶ ἕν</span>; 2Rs 12:1; Sir 34:23s.: <span class=\"greek\">εἷς</span> … <span class=\"greek\">καὶ εἷς</span>; Est 10:3g: <span class=\"greek\">δύο</span>, <span class=\"greek\">ἕνα τῷ λαῷ</span> … <span class=\"greek\">καὶ ἕνα τ</span>. <span class=\"greek\">ἔθνεσιν</span>, «dois: um para o povo… e outro para as nações»; TestJob 51:3: <span class=\"greek\">μιᾶς ὑποσειμιούσης τῇ μιᾷ</span>.) Mt 20:21; 24:40s.; 27:38; Jo 20:12; Gl 4:22; B 7:6s. <span class=\"greek\">εἷς τὸν ἕνα</span>, «uns aos outros» (= <span class=\"greek\">ἀλλήλους</span>), 1Ts 5:11 (cf. Teócrito 22, 65: <span class=\"greek\">εἷς ἑνί</span>, «um ao outro»; TestJob 27:3: <span class=\"greek\">εἷς τόν ἕνα κατέρραξαν</span>, «derrubaram uns aos outros»).</p>\n<p><strong>ⓑ <span class=\"greek\">εἷς</span> … <span class=\"greek\">εἷς</span> … <span class=\"greek\">εἷς</span>, «um… outro… um terceiro»</strong>, Mt 17:4 (cf. 1Rs 10:3; 13:17, 18).</p>\n<p><strong>ⓒ <span class=\"greek\">εἷς ἕκαστος</span>, «cada um, cada indivíduo»</strong>, reforçando <span class=\"greek\">ἕκαστος</span>; como adjetivo, Ef 4:16; sobretudo substantivado, veja <span class=\"greek\">ἕκαστος</span> b.</p>\n<p><strong>ⓓ <span class=\"greek\">ὁ εἷς</span> … <span class=\"greek\">ὁ ἕτερος</span>, «um… o outro»</strong> (Aristóteles, De Rep. Ath. 37, 1; Hipérides 5, 14s.; UPZ 161, 39, 43, 46 [119 a.C.]; PGen 48, 6ss.: <span class=\"greek\">μίαν μὲν</span> … <span class=\"greek\">τὴν δὲ ἑτέραν</span>; BGU 194, 15s.; Est 5:1a; TestAbr A 11, p. 88, 29 [Stone, p. 24]; Justino, D. 49, 2 e outros), Mt 6:24; Lc 7:41; 16:13; 17:34s.; 18:10 e outros. Também <span class=\"greek\">ὁ εἷς</span> … <span class=\"greek\">ὁ ἄλλος</span>, Ap 17:10.</p>\n<p><strong>ⓔ Distribuição</strong> (1Cr 24:6: <span class=\"greek\">εἷς εἷς</span>, «um a um»; AscIs 3:27: <span class=\"greek\">εἷς καὶ εἷς καὶ εἷς ἐν τόποις καὶ τόποις</span>, «um após outro em diferentes lugares»): <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕνα</span>, <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕν</span>, «um de cada vez» (Heródoto, Platão e outros; 1Esdr 1:31; 4Mac 15:12, 14; Josefo, Bell. 4, 240; Ant. 12, 191; Ath. 25, 3: <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕνα καὶ κατὰ ἔθνη</span>, «individualmente e por povos»), ITr 12:2; <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕνα πάντες</span>, «todos, um por um», 1Co 14:31 (cf. Pseudo-Xenofonte, Cyn. 6, 14); <span class=\"greek\">ὑμεῖς οἱ καθ</span>’ <span class=\"greek\">ἕνα ἕκαστος</span>, «cada um de vós», Ef 5:33.</p>\n<p><span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕν</span>, «um após outro» (daí <span class=\"greek\">τὸ καθ</span>’ <span class=\"greek\">ἕν</span>, «lista detalhada»: PLille 11, 8 [século III a.C.]; PTebt 47, 34; 332, 16), Jo 21:25; também <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἓν ἕκαστον</span> (Xenofonte, Cyr. 1, 6, 22; Ages. 7, 1; EpArist 143), At 21:19. <span class=\"greek\">ἓν καθ</span>’ <span class=\"greek\">ἕν</span> (Esopo, Fab. 274 P.; PLeid II, X 1, 22), «cada um», Ap 4:8; nessa passagem o segundo <span class=\"greek\">ἕν</span> poderia ser nominativo não declinado, como em <span class=\"greek\">εἷς κατὰ εἷς</span> (cf. Luciano, Sol. 9; 3Mac 5:34; outros exemplos em W-S. §26, 9; 11; Wetstein I 627), «um após outro», Mc 14:19; Jo 8:9. <span class=\"greek\">τὸ καθ</span>’ <span class=\"greek\">εἷς</span>, em oposição a <span class=\"greek\">οἱ πολλοί</span>, «individualmente», Rm 12:5; mas <span class=\"greek\">κατὰ ἕνα</span> = <span class=\"greek\">ἕκαστον</span>, «cada um», Hs 9, 3, 5; 9, 6, 3 (B-D-F §305). <span class=\"greek\">ἀνὰ εἷς ἕκαστος</span>, «cada um», Ap 21:21.</p>\n<p><strong>ⓕ <span class=\"greek\">ἀπὸ μιᾶς</span></strong>, veja <span class=\"greek\">ἀπό</span> ⑥ (idiomatismo com substantivo subentendido, Mitt-Wilck. I/2, 46, 15 [338 d.C.]: <span class=\"greek\">μίαν ἐκ μιᾶς</span>, isto é, <span class=\"greek\">ἡμέραν</span>, «dia após dia»). — B. 937; 1007s. DELG. M-M. EDNT. TW. Sv.</p></div></section></article> <article id=\"entry-eisago-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσάγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eiságō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Futuro <span class=\"greek\">εἰσάξω</span>, LXX; segundo aoristo <span class=\"greek\">εἰσήγαγον</span>, GJs 10:1; perfeito, segunda pessoa do plural, <span class=\"greek\">εἰσαγειόχατε</span>, 1Rs 21:16; aoristo passivo <span class=\"greek\">εἰσήχθην</span>, LXX (Homero e seguintes). <strong>Trazer ou conduzir para dentro</strong>, com acusativo <span class=\"greek\">τινά</span>, «alguém», Jo 18:16; GJs 18:1; Lc 2:27. Com <span class=\"greek\">τινὰ εἴς τι</span>, «alguém para dentro de alguma coisa» (Xenofonte, An. 1, 6, 11; 4Rs 9:2; Josefo, Ant. 1, 38; Justino, D. 113, 3; Ar. 15, 7: <span class=\"greek\">ὑπὸ στέγην</span>, «sob um teto»): para dentro de uma cidade, At 9:8; quartel, 21:37; 22:24; arena, MPol 6:2; casa, Lc 22:54; B 3:3 (Is 58:7); templo, At 21:28s. (sobre as implicações da alegada violação da santidade do templo, veja Boffo, Iscrizioni, n.º 32, p. 283s., com bibliografia); cf. B 16:9; Ox 840, 8; <span class=\"greek\">ἐν τῷ ναῷ</span>, «no templo», GJs 10:1; para dentro do Reino, MPol 20:2 (cf. TestJob 47:3: <span class=\"greek\">εἰς τὸν μείζονα αἰῶνα</span>, «para o mundo maior»); do mundo, 1Cl 38:3; cf. B 6:16; de um sepulcro, GPt 6:24. <span class=\"greek\">τὸν πρωτότοκον εἰς τὴν οἰκουμένην</span>, «o Primogênito no mundo», Hb 1:6. <span class=\"greek\">ὧδε</span>, «para cá», Lc 14:21. — Com objeto de coisa, <span class=\"greek\">τὶ</span>, At 7:45. — M-M.</p></div></section></article> <article id=\"entry-eisakouo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσακούω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eisakoúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Futuro <span class=\"greek\">εἰσακούσομαι</span>; primeiro aoristo <span class=\"greek\">εἰσήκουσα</span>; perfeito <span class=\"greek\">εἰσακήκοα</span>; voz passiva, primeiro futuro <span class=\"greek\">εἰσακουσθήσομαι</span>, primeiro aoristo <span class=\"greek\">εἰσηκούσθην</span> (veja <span class=\"greek\">ἀκούω</span>; Homero e outros; SEG VIII, 551, 35; 715, 14; LXX; PsSol 6:5; TestSol 1:1 C; TestAbr A; JosAs 15:2, códice A; ParJer 7:32; ApcMos; GrBar 16:4; Justino, D. 28, 2; 72, 1 [citação de fonte desconhecida]; cf. D 14, 4; 37, 4; 64, 4s.; <span class=\"greek\">ἐπ</span>- na LXX). Em geral, «escutar».</p>\n<p><strong>① Obedecer com base numa escuta atenta; obedecer</strong> (Sófocles, Tucídides e outros; PSI 377, 20; Dt 1:43; 9:23; Sir 3:6; 39:13), com genitivo <span class=\"greek\">τινός</span>, «a alguém», 1Co 14:21; 1Cl 8:4 (Is 1:19s.).</p>\n<p><strong>② Escutar com implicação de atenção e resposta; ouvir, atender</strong> (frequentemente na LXX, acerca de Deus que atende súplicas).</p>\n<p><strong>ⓐ Referente à pessoa que faz a petição:</strong> (Quinto de Esmirna 12, 154: a divindade escuta, com genitivo, como em Justino), 1Cl 22:7 (Sl 33:18); 57:5 (Pv 1:28); voz passiva, Mt 6:7; Hb 5:7 (veja <span class=\"greek\">ἀπό</span> ⑤ⓐ).</p>\n<p><strong>ⓑ Referente à oração ou súplica:</strong> (Sl 4:2; Br 2:14; Sir 34:26; Sl 6:5; PsSol 6:5; Josefo, Ant. 1, 190; TestLevi 4:2), Lc 1:13 (cf. Sir 51:11); At 10:31; GJs 20:3 (variante <span class=\"greek\">ἐπ</span>-). — C. Cox, Biblica 62, 1981, 251–258, sobre o uso no Saltério grego. — M-M.</p></div></section></article> <article id=\"entry-eisdechomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσδέχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eisdéchomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Futuro <span class=\"greek\">εἰσδέξομαι</span>; primeiro aoristo <span class=\"greek\">εἰσεδεξάμην</span>, LXX; particípio <span class=\"greek\">εἰσδεξάμενος</span>. Voz passiva, aoristo, terceira pessoa singular <span class=\"greek\">εἰσεδέχθη</span>, 2Mac 4:22 (veja <span class=\"greek\">δέχομαι</span>; Píndaro, Heródoto e outros; inscrições, papiros, LXX; EpArist 103).</p>\n<p><strong>① Receber graciosamente na própria presença; receber, acolher</strong>, 2Co 6:17 (Ez 20:34).</p>\n<p><strong>② Permitir a entrada; receber, admitir</strong>, 1Cl 12:3 (cf. Josefo, Ant. 14, 285: «admitir»). — M-M. TW.</p></div></section></article> <article id=\"entry-eiseimi-go-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴσειμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eíseimi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(De <span class=\"greek\">εἰς</span> + <span class=\"greek\">εἶμι</span>.) Infinitivo <span class=\"greek\">εἰσιέναι</span>; particípio <span class=\"greek\">εἰσιών</span>; imperfeito <span class=\"greek\">εἰσῄειν</span> (Homero e outros; inscrições, papiros, LXX; Josefo; Justino, A I, 47, 6). <strong>Entrar numa área; ir para dentro de</strong>, com <span class=\"greek\">εἴς τι</span>, «alguma coisa» (SIG 982, 3: <span class=\"greek\">εἰς τὸν ναόν</span>, «para dentro do templo»; UPZ 162 VIII, 19 [117 a.C.]; Êx 28:29; Josefo, Bell. 3, 325; Ant. 3, 269: <span class=\"greek\">εἰς τὸ ἱερόν</span>, «para dentro do recinto sagrado»): o templo, At 3:3; 21:26; cf. Hb 9:6; MPol 9:1; <span class=\"greek\">εἰς τὸν οἶκον</span>, «para dentro da casa», GJs 11:1. Com <span class=\"greek\">πρός τινα</span>, «ir a alguém» (Sófocles, Phil. 953; Xenofonte, Cyr. 2, 4, 5; TestJos 3:6), At 21:18. — Frisk, s.v. <span class=\"greek\">εἶμι</span>. M-M.</p></div></section></article> <article id=\"entry-eiserchomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσέρχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eisérchomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Futuro <span class=\"greek\">εἰσελεύσομαι</span> (En 25:6; TestJob 40:4; Justino, A I, 35, 10; Marco Aurélio 10, 8); segundo aoristo <span class=\"greek\">εἰσῆλθον</span> (também <span class=\"greek\">εἰσῆλθα</span>, B-D-F §81, 3; Mlt-H. 208; Mt 7:13; Lc 11:52; imperativo <span class=\"greek\">εἰσελθάτω</span>, Mc 13:15); perfeito <span class=\"greek\">εἰσελήλυθα</span>, LXX; particípio <span class=\"greek\">εἰσεληλυθώς</span>, Hs 9, 12, 4; 9, 13, 4; mais-que-perfeito <span class=\"greek\">εἰσεληλύθει</span>, 2Mac 9:2 (Homero e seguintes).</p>\n<p><strong>① Mover-se para dentro de um espaço; entrar.</strong></p>\n<p><strong>ⓐ Referente a localidades geográficas e outros lugares como destino. <span class=\"greek\">α</span>. Cidades e aldeias com nomes próprios</strong> (Josefo, Ant. 9, 122): «entrar em Jerusalém», Mt 21:10 (Justino, D. 88, 6); <span class=\"greek\">εἰς Ἱεροσόλυμα εἰς τὸ ἱερόν</span>, «em Jerusalém e no templo», Mc 11:11; Cesareia, At 10:24; 23:33; Cafarnaum, Mt 8:5; Mc 2:1; Lc 7:1.</p>\n<p><strong><span class=\"greek\">β</span>. O mundo em geral:</strong> <span class=\"greek\">εἰς τὸν κόσμον</span>, «entrar no mundo» (Fílon, Op. M. 78), com diversos significados: da primeira aparição do pecado e da morte, Rm 5:12; 1Cl 3:4 (cf. Sb 2:24); do nascimento (Marco Aurélio 6, 56), 1Cl 38:3; da encarnação de Cristo, Hb 10:5.</p>\n<p><strong><span class=\"greek\">γ</span>. Áreas construídas e estabelecimentos:</strong> «entrar no santuário», Hb 9:12, 24s.; templo (Josefo, Ant. 3, 319), Lc 1:9; Ap 15:8; casa, Mt 10:12; 12:29; 17:25, variante; Mc 7:17; Lc 1:40; 8:41; At 11:12; 16:15; 21:8; sinagoga (a menos que a acepção «assembleia» se aplique em certas passagens; veja <span class=\"greek\">συναγωγή</span> ④), Mc 1:21; 3:1; Lc 4:16; 6:6; At 13:14; 14:1; 18:19; cf. Tg 2:2; cidade, Mt 10:11; 27:53; Mc 1:45; Lc 10:8, 10; 22:10; At 9:6; 14:20 e outros; aldeia, Mc 8:26; Lc 9:52; 17:12; quartel, At 23:16; pretório, Jo 18:28; 19:9; cf. At 25:23; Mt 6:6; Jo 18:1; Mc 16:5; Jo 20:6; 10:1; Mt 24:38; Lc 17:27; 1Cl 9:4.</p>\n<p><span class=\"greek\">εἰς τ</span>. <span class=\"greek\">νεφέλην</span>, «para dentro da nuvem», Lc 9:34 (cf. Êx 24:18). — Com indicação do lugar de proveniência, <span class=\"greek\">εἰ</span>. <span class=\"greek\">ἔκ τινος</span>: <span class=\"greek\">ἐξ ἀγροῦ</span>, «vir do campo», Lc 17:7 (cf. PEleph 13, 6 [223/222 a.C.]: <span class=\"greek\">οὔπω εἰσελήλυθεν ἐξ ἀγροῦ</span>, «ainda não veio do campo»; Gn 30:16). — Com indicação do lugar pelo qual se entra, <span class=\"greek\">διά τινος</span> (2Cr 23:20; Jo 2:9; Jr 17:25; Josefo, Ant. 13, 229: <span class=\"greek\">εἰ</span>. <span class=\"greek\">δι</span>’ <span class=\"greek\">ἄλλης πύλης</span>, «entrar por outra porta»), Mt 7:13; 19:24, variante; Lc 13:24; 18:25a; Jo 10:1, 2 (variante <span class=\"greek\">ἐρχόμενος</span> no P75), 9.</p>\n<p>Com <span class=\"greek\">ὑπό</span>: <span class=\"greek\">τὴν στέγην</span>, «sob o teto», isto é, «entrar na casa» (Gn 19:8, variante), Mt 8:8; Lc 7:6. — Com advérbio: <span class=\"greek\">εἰ</span>. <span class=\"greek\">ἔσω</span>, «entrar» (2Cr 29:18; Bel 19, Teodócio), Mt 26:58; AcPl Ha 4, 3; <span class=\"greek\">ὧδε</span>, «entrar aqui» (Zc 7:3; Ez 40:4), At 22:12; <span class=\"greek\">ὅπου ἐὰν εἰσέλθῃ</span>, «onde quer que ele entre», Mc 14:14; Hb 6:20. — Sem ênfase no elemento preposicional, Mt 9:18, variante (veja <span class=\"greek\">εἷς</span> ③ⓑ; <span class=\"greek\">προσέρχομαι</span> ①ⓐ).</p>\n<p><strong><span class=\"greek\">δ</span>. Frequentemente o lugar de destino não é mencionado</strong>, mas pode ser deduzido do contexto (Tb 5:9; 8:13; Jd 14:14; 1Mac 7:36; 2Mac 1:15 e outros; PTebt 418, 6ss.): <span class=\"greek\">εἰσελθὼν διήρχετο τὴν Ἰεριχώ</span>, «entrou em Jericó e a atravessava», Lc 19:1; <span class=\"greek\">καὶ ὅτε εἰσῆλθον</span> (subentendido <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">οἶκον</span>), «quando haviam entrado [na casa]», At 1:13; <span class=\"greek\">μὴ εἰσελθάτω</span> (subentendido <span class=\"greek\">εἰς τὴν οἰκίαν</span>), «não entre [na casa]», Mc 13:15; também <span class=\"greek\">εἰσελθοῦσα</span>, Mc 7:25, variante; <span class=\"greek\">εἰσελθών</span>, Mt 9:25; cf. At 5:7, 10; 10:25; 1Co 14:23s.; AcPl Ha 3, 13.</p>\n<p>Mas a ideia de destino pode ser tão pouco importante que <span class=\"greek\">εἰ</span>. passa a significar simplesmente <strong>vir, ir</strong>, Lc 18:25a; cf. Mt 19:24 (veja ①ⓐ<span class=\"greek\">γ</span> acima). — De coisas: «ir [para dentro], vir [para dentro], entrar»; de alimentos, na boca (Ez 4:14; Dn 10:3), Mt 15:11 (cf. Sextus 110; TestJob 38:3: <span class=\"greek\">διὰ στόματος τροφὴ εἰσέρχεται</span>, «o alimento entra pela boca»); At 11:8.</p>\n<p><strong>ⓑ Referente a seres como destino. <span class=\"greek\">α</span>. Aproximar-se ou ir a alguém:</strong> <span class=\"greek\">πρός τινα</span>, «vir ou ir a alguém» (Xenofonte, Mem. 3, 10, 1; Cebes, Tab. 29; Josefo, Ant. 8, 235; Gn 16:4; Sl 50:2; Jd 12:13; 15:9), Mc 15:43; Jo 14:23, variante; At 10:3; 11:3; 16:40; Ap 3:20; 1Cl 12:4.</p>\n<p><strong><span class=\"greek\">β</span>. Entrar no meio de outros:</strong> <span class=\"greek\">εἴς τινα</span>, «ir ou entrar entre pessoas», <span class=\"greek\">εἰς τὸν δῆμον</span>, «entre a multidão», At 19:30; <span class=\"greek\">εἰς ὑμᾶς</span>, «entre vós», At 20:29. <span class=\"greek\">ἐπί τινα</span>, «vir a alguém» (cf. Ez 44:25): <span class=\"greek\">ἐν παντὶ χρόνῳ ᾧ εἰσῆλθεν καὶ ἐξῆλθεν ἐφ</span>’ <span class=\"greek\">ἡμᾶς</span>, «todo o tempo em que entrou e saiu entre nós», isto é, «conviveu conosco», At 1:21 (sobre <span class=\"greek\">εἰσέρχομαι καὶ ἐξέρχομαι</span>, cf. Eurípides, Phoen. 534: <span class=\"greek\">ἐς οἴκους</span> … <span class=\"greek\">εἰσῆλθε κἀξῆλθ</span>’ [<span class=\"greek\">καὶ ἐξῆλθε</span>], «entrou nas casas e saiu»; Nm 27:17; 2Cr 1:10; Jo 10:9).</p>\n<p><strong><span class=\"greek\">γ</span>. Entrar no interior de pessoas ou animais; penetrar em alguém</strong> (Sb 1:4, acerca da sabedoria; Josefo, Ant. 4, 121, acerca do espírito divino que entra nos profetas), sobretudo de espíritos hostis que tomam posse do corpo de alguém como sua morada, Mc 9:25; Lc 8:30 (Luciano, Philops. 16: o exorcista pergunta aos espíritos <span class=\"greek\">ὅθεν</span> [<span class=\"greek\">οἱ δαίμονες</span>] <span class=\"greek\">εἰσεληλύθασιν εἰς τὸ σῶμα</span>, «de onde [os demônios] haviam entrado no corpo»; ApcSed 5:5: [<span class=\"greek\">διάβολος</span>] <span class=\"greek\">ὡς καπνὸς εἰσέρχεται εἰς τὰς καρδίας τῶν ἀνθρώπων</span>, «[o diabo] entra como fumaça nos corações dos homens»). Dos espíritos hostis que entram nos porcos, Mc 5:12s.; Lc 8:32s. De Satanás que entra em Judas, Lc 22:3; Jo 13:27; ou numa pessoa, Hm 12, 5, 4. Em vez disso também <span class=\"greek\">εἰ</span>. <span class=\"greek\">ἔν τινι</span> (veja <span class=\"greek\">ἐν</span> ③): <span class=\"greek\">εἰσῆλθεν ἐν αὐτοῖς</span>, «entrou neles», Ap 11:11; cf. Lc 9:46; 1Cl 48:2 (Sl 117:19).</p>\n<p><strong>② Entrar num acontecimento ou estado</strong>; acerca de pessoas: <strong>participar de alguma coisa, vir a desfrutá-la</strong> (Josefo, C. Ap. 2, 123: <span class=\"greek\">εἰς τοὺς ἡμετέρους νόμους</span>, «entrar sob nossas leis»). <span class=\"greek\">εἰς τὴν βασιλείαν τ</span>. <span class=\"greek\">θεοῦ</span> (<span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῶν</span>), «entrar no Reino de Deus [dos céus]», Mt 5:20; 7:21; 19:24; Mc 9:47; 10:15, 23ss.; Lc 18:17, 25; Jo 3:5; 2Cl 6:9 e outros (cf. Dn 11:9). No mesmo sentido, <span class=\"greek\">εἰς τὴν ζωήν</span>, «entrar na vida eterna», isto é, alcançá-la, Mt 18:8s.; 19:17; Mc 9:43, 45. H. Windisch, Die Sprüche vom Eingehen in das Reich Gottes, ZNW 27, 1928, 163–192.</p>\n<p><span class=\"greek\">εἰς τὴν κατάπαυσιν</span>, «entrar no descanso», Hb 3:11, 18; 4:1, 3, 5s., 10s. (todos Sl 94:11); <span class=\"greek\">μέχρι δουλείας εἰσελθεῖν</span>, «chegar até a condição de escravidão», 1Cl 4:9. Referente a Cristo: <span class=\"greek\">εἰ</span>. <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">δόξαν αὐτοῦ</span>, «entrar em sua glória», Lc 24:26. De tentações: <span class=\"greek\">εἰ</span>. <span class=\"greek\">εἰς πειρασμόν</span>, «entrar em tentação», Mt 26:41; Lc 22:40, 46; <span class=\"greek\">εἰς χαράν</span>, «na alegria», Mt 25:21, 23; Pol 1:3. <span class=\"greek\">εἰς τὸν κόπον τινός</span>, «entrar no trabalho de outrem», isto é, desfrutar o fruto do trabalho alheio, Jo 4:38 (cf. Pv 23:10).</p>\n<p>Também nesse emprego (veja ①ⓐ<span class=\"greek\">δ</span> acima), o destino não precisa ser mencionado, podendo ficar subentendido, Mt 7:13; 23:13; Lc 11:52 (cf. 3Mac 1:12); Rm 11:25.</p>\n<p><strong>③ Acontecer, com ênfase no aspecto inicial; ocorrer, desenvolver-se.</strong> Acerca de pensamentos: <span class=\"greek\">εἰσῆλθεν δὲ διαλογισμὸς ἐν αὐτοῖς</span>, «surgiu entre eles uma discussão», Lc 9:46; <span class=\"greek\">εἰς τὰ ὦτά τινος</span>, «chegar aos ouvidos de alguém» (Sl 17:7), Tg 5:4; «penetrar até», Hb 6:19. — M-M. TW.</p></div></section></article> <article id=\"entry-eisegagon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσηγαγον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eisḗgagon⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">εἰσάγω</span>.</p></div></section></article> <article id=\"entry-eisegeomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσηγέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eisēgéomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Primeiro aoristo <span class=\"greek\">εἰσηγησάμην</span> (Simônides, em Ateneu 15, 680d, códice A [veja Diehl, fragmento 71, com a correção <span class=\"greek\">ἁγεῖται</span> proposta por Wilamowitz]; Heródoto e outros; papiros; Sl 63:6, Símaco; Pseudo-Eupólemo, p. 198, 14s. Denis [em Eusébio, PE 9, 17, 8]; Josefo, Fílon, Taciano; em geral, «conduzir para dentro, introduzir»). <strong>Mobilizar ou aplicar algo a uma questão; manifestar, aplicar.</strong> <span class=\"greek\">πᾶσαν εἰσήγησαι σπουδήν</span>, «emprega todo esforço, não percas tempo», AcPlCor 1:16. — DELG, s.v. <span class=\"greek\">ἡγέομαι</span>.</p></div></section></article>"};
